    },
    [13187] = {
        id = 13187,
        text = "기억 파편",
        minipack = 0,
    },
    [2081035] = {
        id = 2081035,
        text = "바다의 공주 모습의 바비 인형, 사랑 때문에 바닷속 깊은 곳에 유폐되었고, 얼굴에서 슬픔을 엿볼 수 있다.",
        minipack = 0,
    },
    [2081036] = {
        id = 2081036,
        text = "집에서 바느질에 흔히 쓰는 무명실, 산뜻한 색채로 인해 많은 사랑을 받는다.",
        minipack = 0,
    },
    [471116] = {
