        minipack = 0,
    },
    [2081379] = {
        id = 2081379,
        text = "작은 땅콩에는 활력이 담겨 있어 향기를 더욱 짙게 만들어 준다.",
        minipack = 0,
    },
    [2081380] = {
        id = 2081380,
        text = "무더운 단오절에 고기가 빠질 순 없는 법, 살코기와 비계를 잘 섞어 연잎밥을 만들면 마법 같은 맛을 낼 수 있다.",
        minipack = 0,
    },
    [2081381] = {
        id = 2081381,
        text = "노른자를 연잎밥에 넣으면 식감도 좋아지고, 금색 빛깔 덕분에 탐스러운 느낌이 난다.",
        minipack = 0,
    },
    [2081382] = {
        id = 2081382,
        text = "달콤한 연잎밥에 빠질 수 없는 단팥, 투박함과 섬세한이 어우러진 식감, 풍부한 향이 일미다.",
        minipack = 0,
    },
    [2081383] = {
        id = 2081383,
        text = "대추는 보양 효과가 있고, 새콤달콤한 맛은 잊을 수 없는 여름날의 추억을 선사한다.",
        minipack = 0,
    },
