    [13310515] = {
        id = 13310515,
        text = "형태가 기괴한 파편, 안에는 뭔가 영상 같은 것이 움직이고 있다. 모든 파편 수집 시 소장 CG를 활성화할 수 있다.",
        minipack = 0,
    },
    [13310523] = {
        id = 13310523,
        text = "형태가 기괴한 파편, 안에는 뭔가 영상 같은 것이 움직이고 있다. 모든 파편 수집 시 소장 CG를 활성화할 수 있다.",
        minipack = 0,
    },
    [13310531] = {
        id = 13310531,
        text = "친애하는 서약자님: \n 봄과 여름이 교차하는 이 시기, 오픈 이래 최대 규모의 업데이트를 준비했습니다!\n 샤람의 문, 영역 쟁탈전, 룬 도전 시스템 등 이번에 준비한 대량의 신규 콘텐츠가 유저 여러분의 마음에 들기를 바라며, 더욱 즐겁게 게임을 즐기실 수 있길 바랍니다. \n 핫게임 스튜디오에 대한 여러분의 격려와 성원에 감사드립니다!\n 그럼, 우리들의 전쟁은 계속됩니다!\n 핫게임 스튜디오",
        minipack = 0,
    },
    [13310539] = {
        id = 13310539,
        text = "친애하는 서약자님: \n 이제 또 한 명의 매력이 충만한 아이돌이 여러분 앞에 곧 모습을 드러냅니다! 만인의 연인 마유리의 목소리 구현은 이미 완료되었습니다. 마유리에게 듣고 싶은 이야기가 있으신가요?\n 성우님의 작업 일정으로 인해 이번 버전과 동시에 출시되지 못하는 점은 정말 안타깝지만, 결코 의도적인 지연은 아닌 점을 말씀드립니다.\n 핫게임 스튜디오는 최상의 콘텐츠를 제공하기 위해 끊임없이 노력하고 있습니다. 조금 늦더라도, 모자람이 있어서는 안 되니까요. \n 핫게임 스튜디오",
        minipack = 0,
    },
    [13310547] = {
        id = 13310547,
        text = "모든 것이 소중한 추억이다.",
        minipack = 0,
    },
    [13310555] = {
        id = 13310555,
        text = "와라! 네 마음껏 나를 칭찬해보아라. 이...이건 또 무슨 이상한 요구인 건데!",
        minipack = 0,
    },
    [13310563] = {
        id = 13310563,
        text = "코토리, 토카와 함께 크리스마스트리 장식을 만들면서, 생각지도 못한 선물을 받게 되었다.",
        minipack = 0,
    },
    [252021] = {
