    [13316027] = {
        id = 13316027,
        text = "산장에서 고용한 메이드, 외모는 귀엽지만 2% 부족하여 항상 사고를 친다. 개인적으로는 슈퍼스타 이자요이 미쿠의 충실한 팬이라고 한다.",
