    [13316043] = {
        id = 13316043,
        text = "아직 학교에 다니고 있는 소녀, 냉정한 사고력은 그녀가 탐정의 든든한 조력자가 되기 충분하다.",
        minipack = 0,
    },
    [910108] = {
        id = 910108,
        text = "평범한 진리",
        minipack = 0,
    },
    [13316059] = {
        id = 13316059,
        text = "음? 농담하지 말라고, 존경하는 고객님.",
        minipack = 0,
    },
    [910109] = {
        id = 910109,
        text = "새 친구의 선물",
        minipack = 0,
    },
    [910110] = {
        id = 910110,
        text = "전투 연습",
        minipack = 0,
    },
    [910111] = {
        id = 910111,
        text = "토카와 오리가미의 목숨을 건 전투, 아무래도 내가 다치는 방법으로만 싸움을 막을 수 있을 것 같다.",
        minipack = 0,
    },
    [13316107] = {
        id = 13316107,
        text = "Day.7",
        minipack = 0,
    },
    [910112] = {
        id = 910112,
        text = "비록 몸은 사격에 당했지만, 토카와 오리가미가 화해한 것을 보니 안심이 되었다.",
        minipack = 0,
    },
    [910113] = {
        id = 910113,
        text = "토끼 머리띠를 놓고 토카와 오리가미가 쟁탈전을 벌이고 있다. 두 사람에게 그냥 평범한 소녀가 되는 건 힘든 일일까?",
        minipack = 0,
    },
    [63028] = {
        id = 63028,
        text = "마음에 드는 정령에게 가장 예쁜 옷을 입혀 언제든지 자신의 앞에 나타나게 하고 싶나요?\n\n1. 간판녀 메뉴에서는 각 정령의 복장 상태를 자유롭게 변경할 수 있고, 메인 페이지의 간판녀로 설정할 수 있습니다.\n\n2. 좌측의 간판녀 프로필 목록에서 개방된 정령 프로필을 선택하고, 우측의 '교체 확인'을 터치하면 간판녀를 교체할 수 있습니다.\n\n3. 교체 전 '갈아입기', '정보', '동작' 3개의 탭에서 정령들의 관련 내용을 미리 확인할 수 있습니다.\n\n4. '갈아입기' 탭: 이곳에서는 정령 복장 카드를 슬라이드해 해당 정령의 모든 복장과 착용 효과를 확인할 수 있습니다.\n\n5. '정보' 탭: 이곳에서는 해당 정령의 기본 정보와 소개를 확인할 수 있고, 그녀들의 개인적인 비밀도 조금은 알 수 있습니다.\n\n6. '동작' 탭: 이곳에서는 정령을 터치할 때 발생하는 동작을 확인할 수 있고, 호감도가 일정 조건을 달성하기 전까지는 대사만 볼 수 있습니다.\n\n7. 메뉴 내 모든 '미개방' 내용은 터치해 확인할 수 있으므로, '사전 공략'을 위해 참고할 수 있습니다.\n-----------------------------------------------\n\n순환 재생 기능이 출시되었습니다!\n\n이제 여러 정령과 복장(고급 코스튬 한정)을 선택해 간판녀로 설정할 수 있습니다. 순환 재생 개방 시 일정 시간마다 메인 화면에 자동으로 다음 간판녀가 등장합니다.",
        minipack = 0,
    },
    [910114] = {
        id = 910114,
        text = "토카의 특수 치료 덕분에 내 혈류량도 증폭됐고, 요시노에게도 가르쳐 줄 필요가 있다는 생각이 들었다.",
        minipack = 0,
    },
    [910115] = {
        id = 910115,
        text = "나는 오리가미가 고의로 잘못을 했다고 생각하지 않는다. 그래서 진심으로 쿠사카베 선배가 이를 가볍게 처리해 주길 바랐다.",
        minipack = 0,
    },
    [910116] = {
        id = 910116,
        text = "좁은 골목에서 우리는 더는 오리가미로부터 도망칠 수 없었고, 결전이 곧 벌어지려 했다.",
        minipack = 0,
    },
    [910117] = {
        id = 910117,
        text = "오리가미의 추격을 따돌렸다고 생각했지만, 토카의 가슴 앞에 갑자기 저격총의 조준점이 나타났다...",
        minipack = 0,
    },
    [13316203] = {
        id = 13316203,
        text = "애도곡의 가사",
        minipack = 0,
    },
    [910118] = {
        id = 910118,
        text = "토카는 이미 궁지에 몰렸다. 부디 내 손안의 토끼 머리띠가 효력이 있었으면 좋겠다.",
        minipack = 0,
    },
    [13316219] = {
        id = 13316219,
        text = "증아마미야 가의 딸",
        minipack = 0,
    },
    [910119] = {
        id = 910119,
        text = "서서히 정신을 차린 나는 가까운 곳에서 전해지는 향기를 맡았고, 토카의 얼굴이 바로 내 앞에 있었다.",
        minipack = 0,
    },
    [13316235] = {
        id = 13316235,
        text = "「분석」유즈루의 상세한 진술",
        minipack = 0,
    },
    [910120] = {
        id = 910120,
        text = "극도로 은폐된 저격은 토카도 피할 수가 없었다. 설마 그녀가 이렇게 죽게 되는 걸까?",
        minipack = 0,
    },
    [13316251] = {
        id = 13316251,
        text = "이건 아마 대중 작가가 고인이 된 친구를 위해 쓴 애도곡 인 것 같다. 가사에는 친구에 대한 그리움이 가득하다.",
        minipack = 0,
    },
    [910121] = {
        id = 910121,
        text = "최대한 토카가 오리가미와 떨어지게 만들자",
        minipack = 0,
    },
    [13316267] = {
        id = 13316267,
        text = "The daughter of the Amamiya family is Suzu Amamiya, who's holding a doll held with nearly the same body proportion as herself.",
        minipack = 0,
    },
    [910122] = {
        id = 910122,
        text = "오리가미의 다음 계획을 알아내서 막자",
        minipack = 0,
    },
    [13316283] = {
        id = 13316283,
        text = "[복도]에서 퍼즐 조각의 종적이 나타났습니다",
        minipack = 0,
    },
    [910123] = {
        id = 910123,
        text = "오리가미가 공격을 당하는 동안 추적에서 벗어나자",
        minipack = 0,
    },
    [13316299] = {
        id = 13316299,
        text = "「비밀 통로 출구」어둡고 비좁은 통로를 따라 앞으로 기어가면서, 우리는 드디어 출구에 다다랐다. 이 비밀 통로는 불이 난 방과 복도와 이어져 있었다니, 설마 범인이 바로 이 통로를 통해 미쿠를 옮긴 것일까?",
        minipack = 0,
    },
    [910124] = {
        id = 910124,
        text = "오리가미가 점차 추격해온다. 아무래도 반드시 상황을 뒤집어야겠어",
        minipack = 0,
    },
    [13316315] = {
        id = 13316315,
        text = "개인 범인 검거 보상",
        minipack = 0,
    },
    [910125] = {
        id = 910125,
        text = "몸에 중상을 입었다. 어서 회복해야 해",
        minipack = 0,
    },
    [13316331] = {
        id = 13316331,
        text = "[이벤트]천둥과 비의 산장",
        minipack = 0,
    },
    [910126] = {
        id = 910126,
        text = "피할 수 없다면 결전을 준비하는 게 좋겠어",
        minipack = 0,
    },
    [910127] = {
        id = 910127,
        text = "피난 지점을 선택해 최대한 오리가미에게서 벗어나자",
        minipack = 0,
    },
    [910129] = {
        id = 910129,
        text = "한 텐트 안에서",
        minipack = 0,
    },
    [63029] = {
        id = 63029,
        text = "캐릭터 공략 메뉴에서 해당 캐릭터의 기본 정보와 스킬 정보를 볼 수 있으며, 캐릭터 획득 전에도 이곳에서 캐릭터의 능력 등을 간략히 확인할 수 있습니다. 해당 캐릭터를 상세하게 체험하고 싶다면, 모의 던전을 진행하는 것이 좋습니다.",
        minipack = 0,
    },
    [910130] = {
        id = 910130,
        text = "빛나는 폭죽",
        minipack = 0,
    },
    [13316411] = {
        id = 13316411,
        text = "Pirate",
        minipack = 0,
    },
    [910131] = {
        id = 910131,
        text = "견우와 직녀",
        minipack = 0,
    },
    [13316427] = {
        id = 13316427,
        text = "Act Alone",
        minipack = 0,
    },
    [20251] = {
        id = 20251,
        text = "Eminent Lady",
        minipack = 0,
    },
    [13316443] = {
        id = 13316443,
        text = "Girl's Predicament",
        minipack = 0,
    },
    [910133] = {
        id = 910133,
        text = "수많은 폭죽이 검은 밤하늘에서 서로 경쟁하듯 피어올랐고, 나는 눈앞의 오리가미의 마음속에... 이상한 기분이 폭죽처럼 솟아오르는 것을 보았다...",
        minipack = 0,
    },
    [13316459] = {
        id = 13316459,
        text = "Snow Fairy",
        minipack = 0,
    },
    [910134] = {
        id = 910134,
        text = "오리가미와 함께 광활한 별하늘을 감상하고, 견우성과 직녀성을 보며 소원을 빌어 봐!",
        minipack = 0,
    },
    [13316475] = {
        id = 13316475,
        text = "Treasure Poacher",
        minipack = 0,
    },
    [910135] = {
        id = 910135,
        text = "내 시선은 점차 흐려졌고... 깨어났을 땐 텐트 안에 있었다. 이불 안에... 누군가 있는 것 같은데?",
        minipack = 0,
    },
    [13316491] = {
        id = 13316491,
        text = "What kind of adventure awaits me in the depth of the monster nest?",
        minipack = 0,
    },
    [910136] = {
        id = 910136,
        text = "눈앞의 오리가미의 마음속에... 이상한 기분이 폭죽처럼 솟아오르는 것을 보았다...",
        minipack = 0,
    },
    [13316507] = {
        id = 13316507,
        text = "    Event Time \n  %s\n%s",
        minipack = 0,
    },
    [910137] = {
        id = 910137,
        text = "어느새 학급 캠프도 막바지에 이르렀다... 오리가미와 함께 광활한 밤하늘을 감상하자!",
        minipack = 0,
    },
    [910138] = {
        id = 910138,
        text = "학급 활동은 캠핑이다. 뭔가 준비할 게 있는지 어서 살펴보자!",
        minipack = 0,
    },
    [910139] = {
        id = 910139,
        text = "자유 활동 시간, 방금 괜한 걸음을 한 것 같은데...",
        minipack = 0,
    },
    [910140] = {
        id = 910140,
        text = "저녁은 모두 함께 바비큐를 해 먹는다. 어서 가서 준비를 도와주자! 하지만 오리가미와 토카의 시합 내용은 정말 신경이 쓰인단 말이지...",
        minipack = 0,
    },
    [910141] = {
        id = 910141,
        text = "저녁 무렵이 됐다. 끝내기로 약속했던 일들이 잔뜩 있다. 얼른 산을 내려가자!",
        minipack = 0,
    },
    [910142] = {
        id = 910142,
        text = "오리가미의 바비큐에 감동하긴 했지만, 지금 난 배가 고파 죽을 지경이다... 그나저나 오리가미가 설마 계속해서 나랑 한 텐트에서 자려는 건 아니겠지...?",
        minipack = 0,
    },
    [13316603] = {
        id = 13316603,
        text = "Oolong Tea",
        minipack = 0,
    },
    [910143] = {
        id = 910143,
        text = "이제 곧 별을 보기 가장 좋은 시간이 된다. 오리가미와 함께 밤하늘의 별을 보고 싶어...",
        minipack = 0,
