    [190010128] = {
        id = 190010128,
        text = "카드 효과，크리티컬 피해+10%",
        minipack = 0,
    },
    [910225] = {
        id = 910225,
        text = "고양이는 잔인하게 바다에 떨어졌다. 쿠루미는 고양이를 구해낼 수 있을까?",
        minipack = 0,
    },
    [63035] = {
        id = 63035,
        text = "희귀도가 높은 보석은 직접 획득하는 방법 외에도 낮은 희귀도의 보석과 도면을 가지고 합성해 획득할 수 있습니다. \n C/B/A급 희귀도의 보석 합성 시에는 합성 도면이 필요하지 않습니다. 합성 재료 역시 희귀도의 제한이 있으며, 합성 결과는 해당 희귀도의 보석 중에서 랜덤으로 획득합니다. S/SS/SSS급의 보석 합성 시에는 합성 도면을 사용해야 하며, 해당 도면이 속한 캐릭터와 일치하는 보석만 합성 재료로 사용할 수 있습니다. 합성 결과는 도면이 속한 캐릭터 및 스킬 슬롯에 따라 보석을 획득합니다. \n 분류 버튼을 터치해 도면 또는 재료를 빠르게 분류할 수 있습니다. 도면 또는 재료가 비교적 많을 때는 분류 버튼을 활용해 보세요.",
        minipack = 0,
    },
    [910226] = {
        id = 910226,
        text = "곧 달을 감상하기 가장 좋은 때가 된다. 코토리가 말한 낭만적인 전개는 대체 무엇일까?",
