    [910265] = {
        id = 910265,
        text = "나는 인기 스타",
        minipack = 0,
    },
    [11221451] = {
        id = 11221451,
        text = "[산 뽑기] 기술 피해 10% 감소, AABBB 기술의 마지막 일격이 목표 정중 후 3초 동안 슈퍼아머를 획득한다",
        minipack = 0,
    },
    [910266] = {
        id = 910266,
        text = "힘든 준비 작업이 마침내 끝났지만, 공연은 그다지 순조롭지 않은 것 같다.",
        minipack = 0,
    },
    [910267] = {
        id = 910267,
        text = "레이네가 무의식적으로 착용한 고양이 복장, 나츠미에게 입혀 주면 어떤 효과가 있을까?",
        minipack = 0,
    },
    [910268] = {
        id = 910268,
        text = "상자 안에는 대체 무슨 비밀이 숨겨져 있는 걸까, 어째서 나츠미가 어른으로 변한 것일까?",
        minipack = 0,
    },
    [910269] = {
        id = 910269,
        text = "아이돌의 훈련이 효과가 있었던 것 같다. 나츠미의 모습에서 자신감이 느껴진다.",
        minipack = 0,
    },
    [910270] = {
        id = 910270,
        text = "의외의 넘어짐으로 당신은 진심을 드러냈고, 처음 만났을 때처럼 당신은 나츠미를 감동시켰다.",
        minipack = 0,
    },
    [910271] = {
        id = 910271,
        text = "고양이가 날 정복했고, 모든 관객을 정복했어. 지금은 고양이 소녀의 밤이야.",
        minipack = 0,
    },
    [910272] = {
        id = 910272,
        text = "마술은 애초부터 가장 멋진 공연이다. 전에도 이렇게 한 마녀가 새로운 방법을 통해 인기 스타가 되었다.",
        minipack = 0,
    },
    [910273] = {
        id = 910273,
        text = "어리둥절한 가운데 사람들의 박수갈채가 멀어져갔고, 나는 나츠미가 더 큰 무대에 오를 수 있을 거라 기대하고 있다.",
        minipack = 0,
    },
    [63038] = {
        id = 63038,
        text = "이벤트 기간 동안 12시간마다 무료로 의뢰를 1번 갱신할 수 있습니다.\n의뢰를 완료하면 많은 보상을 획득할 수 있습니다.\n데이트 의뢰를 완료하면 CG 파편을 획득해 CG를 개방할 수 있습니다.",
        minipack = 0,
    },
