    [61003] = {
        id = 61003,
        text = "결정 돌파",
        minipack = 0,
    },
    [63051] = {
        id = 63051,
        text = "훈련카드는 주간카드와 월간카드로 구성되며, 훈련카드는 구매 즉시 적용되어 정식으로 훈련교관이 될 수 있습니다. \n스크린 문제, 토카 AI의 질문 무시, 훈련 실험실 이벤트를 통해 토카 AI에 대해 훈련을 진행하면 전용 정령 AI 순위에 진입하며, 전용 프레임, 전용 호칭 등의 보상을 얻을 수 있습니다. \n훈련카드의 효력은 1주일/1개월 후 만료되며, 만료 시 유저는 더는 훈련을 진행할 수 없습니다. 순위 및 훈련교관 정보도 더는 갱신되지 않습니다.",
        minipack = 0,
    },
    [13322035] = {
        id = 13322035,
        text = "1. 세계에는 여러 고대 문명이 존재하며, 공중함을 보내 탐색할 수 있습니다; 문명에서 사건을 완료하면 더 많은 문명 대륙을 잠금 해제할 수 있습니다",
        minipack = 0,
    },
    [13322043] = {
        id = 13322043,
        text = "9. \"문명 판도\"에서 현재 문명의 대륙 분포 및 각 대륙의 탐색 정보를 볼 수 있습니다",
        minipack = 0,
    },
    [13322051] = {
