        minipack = 0,
    },
    [2200110] = {
        id = 2200110,
        text = "산달폰을 휘둘러 근접 범위 내의 적을 공격, 3단 연속 공격 가능. \n1단： 적에게 공격력 60%만큼 물리 피해를 1회 입힌다. \n2단： 적에게 공격력 70%만큼 물리 피해를 1회 입힌다.\n3단： 적에게 공격력 70%만큼 물리 피해를 1회 입힌다.",
        minipack = 0,
    },
    [13322107] = {
        id = 13322107,
        text = "북유럽 신화에서 \"세계수\"의 아래에 잠복해 있으며, 세계수를 마구 갉아 먹는 사악한 흑룡이자, 중정과 아스가드를 파괴하는 사악한 힘을 지녔고, 암흑으로 이끄는 흑룡의 왕으로 불린다. 공중함 \"니드호그\"는 흑룡왕과 같은 파괴력을 지녔으며, 세간의 경외를 받는다",
        minipack = 0,
    },
    [2200120] = {
        id = 2200120,
        text = "산달폰을 사용해 검기를 발생시켜 전방의 적을 공격한다. \n적에게 공격력의 180%에 해당하는 물리 피해를 3회에 거쳐 입힌다.",
        minipack = 0,
    },
    [30502] = {
        id = 30502,
        text = "식별명 '이프리트 ', 머리끈의 색상에 따라 성격이 변하며 평소에는 겉과 속이 다른 사령관의 형태를 유지한다.",
        minipack = 0,
    },
    [2200130] = {
        id = 2200130,
        text = "할반 헤레브를 소환해 연속으로 4갈래의 거대한 검기를 발생시켜 전방의 적을 공격한다. \n적에게 공격력 750%만큼 물리 피해를 4회에 거쳐 입힌다.",
        minipack = 0,
    },
    [244011] = {
        id = 244011,
        text = "「풋풋한 메이드」가 설거지를 하던 도중 실수로 접시 하나를 깨뜨렸습니다. 매출 -100",
        minipack = 0,
    },
    [2200140] = {
        id = 2200140,
        text = "전방으로 빠르게 일정 거리를 돌진한다.",
        minipack = 0,
    },
    [244012] = {
        id = 244012,
        text = "「풋풋한 메이드」가 열심히 공부하여 만든 카푸치노가 손님들의 사랑을 듬뿍 받고 있습니다",
        minipack = 0,
    },
    [63052] = {
        id = 63052,
        text = "스크린의 문제에 따라 토카 AI의 질문에 답하고, 훈련 실험실 이벤트를 통해 토카 AI에 대해 훈련을 진행할 수 있습니다. \n문제 스크린: 모든 무시된 토카 AI의 대답과 유저가 낸 질문 내용이 기록됩니다. 유저는 모의 훈련을 통해 다시 토카 AI를 상대로 훈련을 진행합니다. 심사 성공 시 문제 스크린의 기존 문제가 삭제되며, 토카 AI의 대답이 랜덤으로 심사에 성공한 훈련 대답으로 대체됩니다. \n토카 AI의 대답 무시: 전용 채팅방에서 토카 AI와 채팅 중 토카 AI의 대답에 무시를 터치하면 토카 AI 훈련으로 이동하며, 기존 문제에 대한 대답 역시 자동으로 문제를 수정해 훈련을 진행합니다. \n훈련 실험실: 토카 AI를 훈련할 문제를 입력해, 토카를 만났을 때 해당 문제에 대해 제시할 수 있는 답변을 모의로 진행하고 기록하며, 해당 훈련이 발생한 상황을 설정하고 제출합니다. \n심사 목록: 훈련 내용의 상태를 기록합니다.",
        minipack = 0,
    },
    [2200160] = {
        id = 2200160,
        text = "토카 등장 시 왕좌과 함께 강림하며, 왕좌 주변의 적을 공격한다. \n적에게 공격력의 300%에 해당하는 물리 피해를 1회 입힌다.",
        minipack = 0,
