        minipack = 0,
    },
    [2200310] = {
        id = 2200310,
        text = "아이스픽을 소환해 전방의 대상을 공격, 3단 연속 공격 가능. \n1단： 적에게 공격력 60%만큼 서리 피해를 1회 입힌다. \n2단： 적에게 공격력 60%만큼 서리 피해를 1회 입힌다.\n3단： 적에게 공격력 60%만큼 서리 피해를 1회 입힌다.",
        minipack = 0,
    },
    [244022] = {
        id = 244022,
        text = "「소탈한 여자아이」가 라면을 주제로, 익살스러운 노래를 창작했습니다. 매출+3000",
        minipack = 0,
    },
    [2200320] = {
