        minipack = 0,
    },
    [244025] = {
        id = 244025,
        text = "「트윈테일 단짝」이 청소를 하다가 실수로 테이블 위에 있는 접시를 엎어버렸습니다. 매출-2000",
        minipack = 0,
    },
    [2200370] = {
        id = 2200370,
        text = "요시농이 전방에 서리 구역을 생성, 0.3초당 공격력의 30%만큼 피해 1회 입히며 3초간 지속. \n영역 피해를 받은 적의 이동속도가 20% 감소한다.",
        minipack = 0,
    },
    [244026] = {
        id = 244026,
        text = "「트윈테일 단짝」이 축축한 물걸레로 바닥을 닦다가 손님이 미끄러 넘어졌습니다. 매출-1000",
        minipack = 0,
    },
    [2200380] = {
