    [2200610] = {
        id = 2200610,
        text = "무라쿠모의 쌍검을 사용해 근접 범위 내의 적을 공격, 3단 연속 공격 가능. \n1단： 적에게 공격력 50%만큼 뇌전 피해를 1회 입힌다. \n2단： 적에게 공격력 30%만큼 뇌전 피해를 2회 입힌다.\n3단： 적에게 공격력 30%/40%만큼 뇌전 피해를 2회 입힌다.",
        minipack = 0,
