    [20271] = {
        id = 20271,
        text = "출시 준비 중",
        minipack = 0,
    },
    [244081] = {
        id = 244081,
        text = "「금기의 홍장미」가 '과일 한 접시'에다 고추장을 첨가해, 손님들의 칭찬을 받았습니다. 매출+4000",
        minipack = 0,
    },
    [2201260] = {
        id = 2201260,
        text = "전방의 적에게 뇌전의 영역을 생성하며, 마력 포격을 발사해 공격력의 800%에 해당하는 뇌전 피해를 입힌다.",
        minipack = 0,
    },
    [2201270] = {
        id = 2201270,
        text = "공중에서 낙하한 후 전방의 적을 날려버리고, 작은 범위 내의 적에게 공격력의 50%에 해당하는 뇌전 피해를 입히고, 다시 전방의 적을 날려 공격력의 100%에 해당하는 뇌전 피해를 입힌다.",
        minipack = 0,
    },
    [30511] = {
        id = 30511,
        text = "신위영장-5번",
        minipack = 0,
    },
    [244083] = {
        id = 244083,
        text = "「금기의 홍장미」가 놀라운 입담으로, 반품을 요구하는 손님을 설득시켰습니다. 매출+2000",
