    [11303018] = {
        id = 11303018,
        text = "[심판의 화살] 매번 피해를 입힐 때 30%의 확률로 3초 동안 자신의 이동속도를 10% 증가한다,",
        minipack = 0,
    },
    [11303026] = {
        id = 11303026,
        text = "[심판의 화살] 제1단의 1번 공격 명중 시 추가로 에너지 1포인트를 획득한다.",
        minipack = 0,
    },
    [2203240] = {
        id = 2203240,
        text = "린네가 전방에 현실과 허실교차의 영역을 소환하고 영역에서는 지속적으로 안에 있는 적을 끌어 당긴다. 그리고 영력 에너지 볼을 소환해 적을 공격하고, 총 공격력 1500%에 해당하는 마력 피해를 입힌다. \n해당 스킬은 영창이 가능하며 영창이 끝나면 시전한다. 소형 에너지 볼 2개를 추가로 방출하려 총 공격력 2160%에 해당하는 마력 피해를 입힌다. \n그리고, 린네가 [현실 파괴] 또는 [몽경 파괴] 발동 시 [허실교차]의 8초간 피해가 30% 증가하며 해당 효과는 중첩되지 않는다.",
        minipack = 0,
    },
    [244205] = {
        id = 244205,
        text = "「파란 울새」가 남성 손님의 사진 요청에 당황해 거절을 했습니다. 매출-3000",
        minipack = 0,
    },
    [11303050] = {
        id = 11303050,
        text = "[뇌폭] 피해를 입힐 때 4%의 확률로 자신의 공격력 30%만큼의 추가 피해를 입힌다. (소환한 파워 볼은 해당 효과를 발동하지 않는다)",
