        minipack = 0,
    },
    [244209] = {
        id = 244209,
        text = "「파란 울새」가 완벽하게 메이드복에 적응해, 도도한 메이드의 모범이 되어 손님들이 마음에 들어합니다.",
        minipack = 0,
