    [2203308] = {
        id = 2203308,
        text = "성광의 빛",
        minipack = 0,
    },
    [2203310] = {
        id = 2203310,
        text = "리오가 성흔을 사용해 3단 공격을 가해 총 캐릭터 공격력의 300%에 해당하는 마력 피해를 입힌다.",
        minipack = 0,
    },
    [2203320] = {
        id = 2203320,
        text = "리오가 전방을 행해 <마법탄> 4개를 발사해 총 캐릭터 공격력의 520%에 해당하는 마력 피해를 입힌다. 추가 효과: [<마력탄> 1개를 발사할 때마다 추가로 <성광의 빛> 결계가 적에게 자동으로 <별 미사일> 1개를 발사해 800%의 마력 피해를 입힌다]",
        minipack = 0,
    },
    [244210] = {
        id = 244210,
        text = "「파란 울새」가 만든 요리가 전부 별미 레벨 S급을 달성해 이윤이 증가했습니다.",
        minipack = 0,
    },
    [2203330] = {
        id = 2203330,
        text = "리오가 마법의 인장을 소환한다. 5초간 지속되며 주변의 적에게 총 캐릭터 공격력의 700%에 해당하는 마력 피해를 입힌다. 그리고 피해를 입힐 때마다 리오 최대 HP 1%에 해당하는 HP를 회복한다. 추가 효과: [해당 스킬 시전 후 추가로 <성광의 빛> 결계가 아군에게 75% 피해감소 효과를 제공한다.] [마법의 인장이 아직 전장에 있을 때 <예광 성환>을 발동하면 에너지 볼 두 개가 인장 주변을 맴돌면서 에너지 볼이 적에게 닿을 때마다 100%의 마력 피해를 입힌다.]",
        minipack = 0,
    },
    [244211] = {
        id = 244211,
        text = "「파란 울새」가 발명한 몇 가지 새로운 요리가 전부 불티나게 팔렸습니다. 매출+5000",
        minipack = 0,
    },
    [2203340] = {
        id = 2203340,
        text = "리오가 공간을 하나 만들고 안에 있는 적은 30% 느려지며, 총 캐릭터 공격력의 720%에 해당하는 마력 피해를 입힌다. 추가 효과: [해당 스킬 시전 후 추가로 <성광의 빛> 결계가 적을 결계의 중심으로 견인한다.] [공간이 아직 전장에 있을 때 <신성 송가>를 발동하면 공간에서 마법 유성이 떨어지면서 총 캐릭터 공격력의 400%에 해당하는 마력 피해를 입힌다.]",
        minipack = 0,
    },
    [2203350] = {
        id = 2203350,
        text = "리오가 에너지를 한곳에 모은 후 지면을 향해 마법 유성을 여러 개 발사하여 총 캐릭터 공격력의 1600%에 해당하는 마력 피해를 입힌다.",
        minipack = 0,
    },
    [244212] = {
        id = 244212,
        text = "「파란 울새」가 모든 메이드의 사랑을 받아, 업무 능력이 대폭 상승했습니다. 매출+4000",
        minipack = 0,
    },
    [2203360] = {
        id = 2203360,
        text = "리오가 하늘에서 떨어지면서 마법 에너지를 방출해 주변의 적에게 총 캐릭터 공격력의 300%에 해당하는 마력 피해를 입힌다.",
        minipack = 0,
    },
    [244213] = {
        id = 244213,
        text = "「파란 울새」가 '말할 수 없는 여장 소년'을 노래해 손님들의 연민을 받았습니다. 매출+3000",
        minipack = 0,
    },
    [2203380] = {
        id = 2203380,
        text = "결계를 하나 만들고 결계 안의 아군은 8초간 방어력이 20% 증가한다. <마법탄> 1개를 발사할 때마다 결계가 적을 향해 <별 미사일> 1개를 발사한다. 캐릭터가 <신성 송가>를 발동한 후 결계가 아군에게 75%의 피해감소 효과를 제공한다. 캐릭터가 <암야 성전>을 발동한 후 결계가 적을 결계의 중심으로 견인한다.",
        minipack = 0,
    },
    [244214] = {
