        minipack = 0,
    },
    [244216] = {
        id = 244216,
        text = "서비스 기간 동안, 카페의 청소 작업을 더 깨끗이 하며, 동시에 망고 아이스컵을 제조할 수 있습니다.",
        minipack = 0,
    },
    [2203420] = {
        id = 2203420,
        text = "요시노가 전방을 넘나들며 경로에 있는 적을 공격해 공격력의 680%에 해당하는 서리 피해를 입힌다. 해당 스킬은 시전 시 추가로 <냉기력> 20포인트를 소모해 자드키엘 공격을 발동한다\n자드키엘 공격: 전방 구역에 발톱 공격을 가해 자신의 공격력 500%에 해당하는 서리 피해를 입히고, [파열] 효과를 부여한다",
        minipack = 0,
    },
    [2203430] = {
        id = 2203430,
        text = "요시노가 빠르게 가장 가까운 목표 위로 뛰어올라 공중에서 적을 명중 시킨 후 다시 발톱 공격을 가한다. 재 시전 전에 공중에서 위치를 조절할 수 있으며, 공격력의 800%에 해당하는 서리 피해를 입힌다. 발톱 공격을 할 때마다 추가로 <냉기력> 20포인트를 소모해 자드키엘 공격을 발동할 수 있다\n자드키엘 공격: 요시노의 발톱 공격을 보조해 공격력의 600%에 해당하는 서리 피해를 입히고, 마지막 공격의 피해량은 700%까지 증가한다. 자드키엘의 매회 공격은 [파열] 효과를 부여한다",
        minipack = 0,
    },
    [244217] = {
        id = 244217,
        text = "서비스 기간 동안, 고객에게 공부 복습을 진행 할 수 있으며, 호화 해물 요리 또한 가장 환영받는 요리가 입니다.",
        minipack = 0,
    },
    [2203440] = {
        id = 2203440,
        text = "요시노가 전방을 덮쳐 목표에 명중한 후 폭우 같은 공격을 퍼부어 공격력의 490%에 해당하는 서리 피해를 입힌다. 해당 스킬은 시전 시 추가로 <냉기력> 60포인트를 소모해 자드키엘 공격을 발동할 수 있다\n자드키엘 공격: 요시노의 발톱 공격을 보조해 공격력의 880%에 해당하는 서리 피해를 입히고, [파열] 효과를 부여한다",
        minipack = 0,
    },
    [244218] = {
        id = 244218,
        text = "서비스 기간 동안, 따뜻한 안부로 손님들이 따듯함을 느끼며, 하트 오므라이스 또한 많은 사람들에게 받아들여집니다.",
        minipack = 0,
    },
    [2203460] = {
        id = 2203460,
        text = "요시노가 전장에 뛰어 들어가면서 경로에 있는 적을 공격해 공격력의 320%에 해당하는 서리 피해를 입히고, [파열] 효과를 부여한다",
        minipack = 0,
    },
    [244219] = {
        id = 244219,
        text = "서비스 기간 동안, 건강 관리의 강점을 살려, 잠을 깨우는 라떼 또한 매우 잘 팔리게됩니다.",
        minipack = 0,
    },
    [2203470] = {
        id = 2203470,
        text = "전방으로 일정 거리를 이동한다.",
        minipack = 0,
    },
    [13204501] = {
        id = 13204501,
        text = "3초마다 발아래에 폭탄을 생성 시켜 2초 후에 폭발시킨다. 적과 아군에게 높은 피해를 입힌다",
        minipack = 0,
    },
    [2203480] = {
        id = 2203480,
        text = "요시노가 천사의 힘을 해방시켜 <냉기력> 20포인트를 얻고, 자신의 공격력이 15% 증가한다. 지속 시간: 10초. \n해당 기간에 캐릭터가 피해를 입힐 시 30%의 확률로 자드키엘이 출현해 자동으로 공격하여 공격력의 800%에 해당하는 서리 피해를 입힌다. 해당 피해는 기본 공격으로 간주되며, 4초의 쿨타임이 적용된다. \n또한, 요시노가 공격을 받을 때 자드키엘이 나타나 반격을 하며 공격력의 300%에 해당하는 서리 피해를 입힌다. 해당 효과는 1초의 쿨타임이 적용된다.",
        minipack = 0,
    },
    [244220] = {
        id = 244220,
        text = "서비스 기간 동안, 파워 마사지술 또한 예상치 못한 효과를 가져다 주며, 야채 샐러드는 많은 사람들이 거리낌 없이 먹는 음식이됩니다.",
        minipack = 0,
