    [13313084] = {
        id = 13313084,
        text = "고양이 눈으로 꿈에서 미래를 볼 수 있다고 한다. 이 힘은 수정구에 봉인되어 점을 보는 용도로 사용한다.",
        minipack = 0,
    },
    [13313092] = {
        id = 13313092,
        text = "아틀란티스에서 굉장히 유행하는 액세서리, 포세이도니아가 전사의 귀환을 기다리고 있다.",
        minipack = 0,
    },
    [13313100] = {
        id = 13313100,
        text = "[공중함 부품]\n특수 항선에 대응할 시, 독특한 작용을 발휘한다. \n아군 공격(보호막 흡수 포함)은 15%의 확률로 적의 현재 HP의 5%에 해당하는 피해를 입힌다. 쿨타임: 3턴.",
        minipack = 0,
    },
    [13313108] = {
        id = 13313108,
        text = "[공중함 부품]\n높은 열 방출 능력과 처리 속도를 지는 합성 장치이다. \n탐색 중, 추가로 5%의 확률로 지휘실 업그레이드 재료가 드랍된다[전송 트랜지스터]",
        minipack = 0,
    },
    [13313116] = {
        id = 13313116,
        text = "[공중함 부품]\n공중함에게 전방위한 자동 방어 기능을 제공해주는 칩이다. \n아군 HP가 10% 증가한다.",
        minipack = 0,
    },
    [13313124] = {
        id = 13313124,
        text = "[공중함 부품]\n메인 엔진을 보호해주는 플러그 장치이다. \n탐색 중, 추가로 5%의 확률로 방어실 업그레이드 재료가 드랍된다[갑옷 합금]",
