    [13313348] = {
        id = 13313348,
        text = "쿤타아 백성은 천신과 접하여 천신의 관심을 받고, 생산력이 증가한다.",
        minipack = 0,
    },
    [13313356] = {
        id = 13313356,
        text = "붉은 개 부족의 강력한 종족 재능, 습득 후 전투 속성이 대폭 증가한다.",
        minipack = 0,
    },
    [13313364] = {
        id = 13313364,
        text = "보름달이 뜨면, 견신족의 야성이 일부 해방된다.",
        minipack = 0,
    },
    [13313372] = {
        id = 13313372,
        text = "야간 시각 훈련은 전사들이 야간 교전 시에 주도권을 가져다준다.",
        minipack = 0,
    },
    [13313380] = {
        id = 13313380,
        text = "모험 정신이 넘치는 대식묘족은 바다 정복에 대한 거대한 꿈을 품고 있으며, 바닷속의 보물을 누구보다도 갈망한다.",
        minipack = 0,
    },
    [13313388] = {
        id = 13313388,
        text = "만약 대식묘족 설탕파와 같은 취향이 있다면, 설탕파 주민들에게 더 많은 선물을 받을 수 있다.",
        minipack = 0,
    },
    [13313396] = {
        id = 13313396,
        text = "바닷속에는 이전 제국의 보물이 수 없이 쌓여있지만, 경험이 가장 풍부한 인어는 보물찾기의 위험을 잘 알고 있다.",
        minipack = 0,
    },
    [13313404] = {
        id = 13313404,
        text = "오리칼쿰은 태양 에너지를 동력으로 변환하는 신기한 광석이며, 전투 시에는 자신에게 보호막을 걸어준다.",
        minipack = 0,
    },
    [13313412] = {
        id = 13313412,
        text = "수만 년이란 세월도 인어족의 비늘을 퇴화시키지 못했으며, 그것은 전투에서 최고의 갑옷이 된다.",
        minipack = 0,
    },
    [13313420] = {
        id = 13313420,
        text = "회색 개 부족의 영공을 침입했기에 적으로 간주 되어 공격을 받고 있습니다. 이제 반격할 차례입니다!",
        minipack = 0,
    },
    [13313428] = {
        id = 13313428,
        text = "버려진 황야의 제단은 본래 쿤타아의 강대 제사의 유적입니다. 비보 「주문 달린 뼈 목걸이」가 세상에 다시 나오기를 기다리고 있습니다.",
        minipack = 0,
    },
    [13313436] = {
        id = 13313436,
        text = "회색 견 부족의 보급 함대를 공격해 적의 보급을 차단하세요.",
        minipack = 0,
    },
    [30613] = {
        id = 30613,
        text = "□유연하고 빠른 근접 공격",
        minipack = 0,
    },
    [13313452] = {
        id = 13313452,
        text = "빙하에서 나타난 신비의 공방에서 연기가 피어오르고 있다. 이곳에는 「천신의 레시피」를 알고 있는 요리사가 있다고 한다.",
        minipack = 0,
    },
    [13313460] = {
        id = 13313460,
        text = "척후함을 처치하고, 흑사자 부족을 매복 지점으로 끌어오세요.",
        minipack = 0,
    },
    [13313468] = {
        id = 13313468,
        text = "아틀란티스의 여왕 '포세이도니아'한테서 연회 초대를 받았지만, 가는 길에 황실 함대의 습격을 받았습니다.",
        minipack = 0,
    },
    [13313476] = {
        id = 13313476,
        text = "심해의 중전에서 신비한 마법진을 발견했습니다. 어인족은 저주를 통해 '포세이도니아'와 아틀란티스 전체를 조종하고 있습니다.",
        minipack = 0,
    },
    [13313484] = {
        id = 13313484,
        text = "수도 포세이도니아 외곽에 위치한 메아리의 전당, 비보 「파도를 부르는 소라」가 바로 이곳에 매장되어 누군가가 찾아주길 기다리고 있다고 한다.",
        minipack = 0,
    },
    [13313492] = {
        id = 13313492,
        text = "아군 함대가 어인족 함대에 포위당했습니다. 즉시 지원하러 가세요.",
        minipack = 0,
    },
    [13313500] = {
        id = 13313500,
        text = "「공중함」초문명의 미지의 구역에 머물고 있습니다. 선원 몇 명을 밖으로 보내 조사해야 합니다.",
        minipack = 0,
    },
    [13313508] = {
        id = 13313508,
        text = "이세계의 중력 변화는 정령의 전투 작전에 영향을 줍니다. 코토리는 중력 정보를 수집해 분석할 인력이 필요하다고 합니다.",
