        text = "[아이스픽] 관통 가능 목표 +3개.",
        minipack = 0,
    },
    [1012605] = {
        id = 1012605,
        text = "게란 후라이는 당연히 반숙에 간장이죠!",
        minipack = 0,
    },
    [10303026] = {
