        text = "벌써 나가려고요? 잠깐만요, 15분만요!",
        minipack = 0,
    },
    [10303058] = {
        id = 10303058,
        text = "[극한 영역] 속도 감소 효과가 40%로 증가한다.",
        minipack = 0,
    },
    [1012608] = {
