        text = "하루 세끼와 점심 휴식 시간이야말로 인생이죠",
        minipack = 0,
    },
    [10303106] = {
        id = 10303106,
        text = "요시노가 목표 명중 시 30%의 확률로 목표에게 몸서리 효과를 부여한다. \n[몸서리 효과는 6초 동안 목표 이동속도 -10%, 5단계까지 중첩 시 목표를 3초동안 빙결시킨다. ]",
        minipack = 0,
    },
    [1012611] = {
        id = 1012611,
        text = "쉿, 조용! 쿠루미 씨가 아직——잉!",
        minipack = 0,
    },
    [1012612] = {
        id = 1012612,
        text = "오후에는 음악 연습이에요...... 뭐, 놀이공원에 갑시다~",
        minipack = 0,
    },
    [1012613] = {
        id = 1012613,
        text = "더는 못 걷겠어요~ 잠시 쉬었다 갑시다~",
        minipack = 0,
    },
    [1012614] = {
        id = 1012614,
        text = "오오! 정말 멋있어 보이는 곳이네요, 어서 보러 가요!",
        minipack = 0,
    },
    [1012615] = {
        id = 1012615,
        text = "쿠루미 씨와의 데이트는 어땠나요? 어서 말해 주시죠~",
        minipack = 0,
    },
    [1012616] = {
        id = 1012616,
        text = "흐아~ 음? 탄산 음료...... 한잔하시겠습니까?",
        minipack = 0,
    },
    [1012617] = {
        id = 1012617,
        text = "돌아왔군요~ 밥이 먼저인가요 아니면 먼저 씻을래요, 아니면——",
        minipack = 0,
    },
    [1012618] = {
        id = 1012618,
        text = "저녁에 친구들과 노래방에 가기로 했는데, 데리로 와주실 건가요~",
        minipack = 0,
    },
    [1012619] = {
        id = 1012619,
        text = "밤하늘이 정말 이쁘네요",
        minipack = 0,
    },
