    },
    [1701990] = {
        id = 1701990,
        text = "[이벤트]설날 축제",
        minipack = 0,
    },
    [1701991] = {
        id = 1701991,
        text = "우와아, 데이트 시작이야? 지금?",
        minipack = 0,
    },
    [1701992] = {
        id = 1701992,
        text = "오늘의 예뻐지기 수업에선 뭘 배우려나?",
        minipack = 0,
    },
    [1701993] = {
        id = 1701993,
        text = "역시 네 녀석이 게임을 잘할 줄 알았다니까.",
        minipack = 0,
    },
    [1701994] = {
        id = 1701994,
        text = "우와, 너랑 데이트하는 건 정말 재밌다니까.",
        minipack = 0,
    },
    [1701995] = {
        id = 1701995,
        text = "흥, 네 녀석도 결국 이런 녀석이었어, 정말 실망이야.",
        minipack = 0,
    },
    [1701996] = {
        id = 1701996,
        text = "그럼 약속 시간에 봐. 반드시 와야 해!",
        minipack = 0,
    },
    [1701997] = {
        id = 1701997,
        text = "어째서 거절하는 건데? 내가 못생겨서 그런 거야?",
        minipack = 0,
    },
    [1701998] = {
        id = 1701998,
        text = "옷 갈아입는 거 훔쳐보면 안 돼!",
        minipack = 0,
    },
    [1701999] = {
        id = 1701999,
        text = "이 옷을 입으면 더 예뻐질 수 있을까?",
        minipack = 0,
    },
    [1702000] = {
        id = 1702000,
        text = "고마워... 내 모습... 예뻐?",
        minipack = 0,
    },
    [1702001] = {
        id = 1702001,
        text = "뭐야? 화장품? 아니면 치마?",
        minipack = 0,
    },
    [1702002] = {
        id = 1702002,
        text = "얼른 보여줘, 숨기지 말고, 다 봤단 말이야!",
        minipack = 0,
    },
    [1702003] = {
        id = 1702003,
        text = "앗! 역시 요시노가 날 속이지 않았어, 정말 맛있어!",
        minipack = 0,
    },
    [1702004] = {
        id = 1702004,
        text = "뭐... 그런대로 괜찮네, 토카가 말한 것처럼 그렇게 과장되진 않았지만.",
        minipack = 0,
    },
    [1702005] = {
        id = 1702005,
        text = "정말 대단해! 이런 건 처음 봐.",
        minipack = 0,
    },
    [1702006] = {
        id = 1702006,
        text = "이거? 그럭저럭 괜찮네, 나도 이렇게 변할 수 있긴 하지만.",
        minipack = 0,
    },
    [1702007] = {
        id = 1702007,
        text = "으, 앞으로도 계속 계속 더욱 더욱 예뻐져야만 해!",
        minipack = 0,
    },
    [1702008] = {
        id = 1702008,
        text = "역시나 내가 제일 예쁜 거지?",
        minipack = 0,
    },
    [1702009] = {
        id = 1702009,
        text = "뭐라고?! 재미있는 게임이 시작된다고?",
        minipack = 0,
    },
    [1702010] = {
        id = 1702010,
        text = "무슨 일이야? 우물쭈물거리고 정말 귀찮게.",
        minipack = 0,
    },
    [1702011] = {
        id = 1702011,
        text = "저 녀석은 나만 괴롭힐 수 있단 말이야!",
        minipack = 0,
    },
    [1702012] = {
        id = 1702012,
        text = "더욱 강해지면 더 많은 사람들을 괴롭힐 수 있겠지, 헤헤.",
        minipack = 0,
    },
    [1702013] = {
        id = 1702013,
        text = "이렇게 재밌는 게임에 내가 빠질 수 없잖아?",
        minipack = 0,
    },
    [1702014] = {
        id = 1702014,
        text = "이 세상에서 녀석을 괴롭힐 수 있는 건 오직 나뿐이야!",
        minipack = 0,
    },
    [1702015] = {
        id = 1702015,
        text = "정령-나츠미 보유",
        minipack = 0,
    },
    [1702016] = {
        id = 1702016,
        text = "나츠미와 임의의 일상 데이트 완료",
        minipack = 0,
    },
    [1702017] = {
        id = 1702017,
        text = "나츠미와 임의의 일상 데이트에서 히든 엔딩 달성",
        minipack = 0,
    },
    [1702018] = {
        id = 1702018,
        text = "나츠미와 임의의 일상 데이트에서 해피 엔딩 달성",
        minipack = 0,
    },
