    [1702053] = {
        id = 1702053,
        text = "[메인]나츠미_챕터1",
        minipack = 0,
    },
    [1702054] = {
        id = 1702054,
        text = "어두운 밤처럼 검고 긴 머리카락을 지닌 소녀, 빛나는 두 눈은 밤하늘에서 가장 빛나는 별과 같다.",
        minipack = 0,
    },
    [1702055] = {
        id = 1702055,
        text = "강력한 전사의 신분이지만, 싹트기 시작하는 소녀의 마음을 숨길 수는 없다.",
        minipack = 0,
    },
    [1702056] = {
        id = 1702056,
        text = "속마음은 유리처럼 연약하고, 낯선 사람을 무서워하는 그녀, 줄곧 당신의 보호가 필요하다.",
        minipack = 0,
    },
    [1702057] = {
        id = 1702057,
        text = "강력하고 잔혹한 힘, 더욱 치명적인 미모.",
        minipack = 0,
    },
    [1702058] = {
        id = 1702058,
        text = "그녀는 영원히 냉정함을 유지하려 하지만, 결국 오빠의 자상함에 빠져버리고 만다.",
        minipack = 0,
    },
    [1702059] = {
        id = 1702059,
        text = "「사랑」은 그녀가 존재하는 유일한 이유, 마치 천사처럼 높은 하늘에 머무르고 있다.",
        minipack = 0,
    },
    [1702060] = {
        id = 1702060,
        text = "오직 믿을 수 있는 사람에게만 진짜 모습을 드러낸다.",
        minipack = 0,
    },
    [1702061] = {
        id = 1702061,
        text = "발렌타인 데이? 으음... 내게 있어서는 그저 너와 데이트를 할 수 있는 날이라면, 그날이 좋은 날이다. \n나와 함께 있으면 너도 즐거운 것이냐? 정말 그런 게냐?",
        minipack = 0,
    },
    [1702062] = {
        id = 1702062,
        text = "친애하는 연인에게, 부디 당신이 오늘 이 몸의 꽃과 러브레터를 받아주길 바라네. \n오거라, 함께 멋진 밤을 보내는 게다!",
        minipack = 0,
    },
    [1702063] = {
        id = 1702063,
        text = "요시노는 이미 전보다 더욱 강해졌어요...\n해...행복한... 발렌타인데이가 되었으면 좋겠어요~",
        minipack = 0,
    },
    [1702064] = {
        id = 1702064,
        text = "어머, 운명으로 정해진 만남이지만, 저도 가끔은 행운이라고 생각해요~\n시간의 강에서 당신을 기다릴게요.",
        minipack = 0,
    },
    [1702065] = {
        id = 1702065,
        text = "바보 오빠, 오늘은 연인들의 날이지만, 나도 오빠한테 하고 싶은 말이 있어. \n줄곧 곁에 있어 줘서 고마워.",
        minipack = 0,
    },
    [1702066] = {
        id = 1702066,
        text = "오늘은 당신의 손을 더 꽉 잡을 거예요. 꽃이 만발한 들판이나, 꽃잎이 떨어지는 나무 아래를 걸어요. \n석양이 우리의 그림자를 늘어트릴 때까지요.",
        minipack = 0,
    },
    [1702067] = {
        id = 1702067,
        text = "사실 나도 가끔은 네게 마음의 문을 열고 싶어...\n그저 가장 좋은 때를 기다리고 있을 뿐이야.",
        minipack = 0,
    },
    [1702068] = {
        id = 1702068,
        text = "[이벤트]초콜릿 대작전",
        minipack = 0,
    },
    [3207501] = {
