    [1702122] = {
        id = 1702122,
        text = "우왓! 노, 농담하지 마요! 얼른 사라져요!",
        minipack = 0,
    },
    [1702123] = {
        id = 1702123,
        text = "후후후, 당신은 절 속일 수 없어요. 제 목소리 외에, 전 아무것도 믿지 않아요.",
        minipack = 0,
    },
    [1702124] = {
        id = 1702124,
        text = "정말인가요? ...제가 목소리를 잃게 되더라도, 제 팬이 되어줄 건가요?",
        minipack = 0,
    },
    [1702125] = {
        id = 1702125,
        text = "에? 갑자기 제 노래가 듣고 싶다구요? 헤헤, 언제든지 좋아요~",
        minipack = 0,
