    [1702136] = {
        id = 1702136,
        text = "어머 어머, 말썽부리면 안 돼요.",
        minipack = 0,
    },
    [1702137] = {
        id = 1702137,
        text = "우후훗, 안이 신경 쓰이나요? 하지만, 안~된~다~구~요~",
        minipack = 0,
    },
    [1702138] = {
        id = 1702138,
        text = "사실... 괜찮아요. 당신에게 쓰러진다 해도, 기꺼이 원하던 바예요.",
        minipack = 0,
    },
    [1702139] = {
        id = 1702139,
        text = "정말 실례네요. 저처럼 「평범」한 여자아이한테 무슨 말을 하는 거예요.",
