    [1702147] = {
        id = 1702147,
        text = "봐라! 반들반들 부드럽고, 정말 편하구나!",
        minipack = 0,
    },
    [1702148] = {
        id = 1702148,
        text = "으음, 이 옷은 걷기 어렵구나...",
        minipack = 0,
    },
    [1702149] = {
        id = 1702149,
        text = "음! 옷이 흘러내렸다! 입는 걸 도와줘라!",
        minipack = 0,
    },
    [1702150] = {
        id = 1702150,
        text = "어서 봐라, 벚꽃 모양의 머리 장식이다. 예쁜 것 같으냐?",
        minipack = 0,
    },
    [1702151] = {
        id = 1702151,
        text = "음... 안에 아무것도 입지 않으니, 조금 불편한 것 같구나...",
        minipack = 0,
    },
    [1702152] = {
        id = 1702152,
        text = "음... 왠지 너무 많이 먹어서 허리띠가 불편한데... 저기, 나를 업어줄 수 있겠느냐?",
        minipack = 0,
    },
    [1702153] = {
        id = 1702153,
        text = "머리띠를 특별한 꽃 모양으로 바꿨어, 예뻐?",
        minipack = 0,
    },
    [1702154] = {
        id = 1702154,
        text = "기모노 안에는 속옷을 입지 않아.",
        minipack = 0,
    },
    [1702155] = {
        id = 1702155,
        text = "선물 고마워, 정말 기뻐.",
        minipack = 0,
    },
    [1702156] = {
        id = 1702156,
        text = "난 입는 것보단 벗는 걸 더 잘해.",
        minipack = 0,
    },
    [1702157] = {
        id = 1702157,
        text = "같이 참배하러 가자.",
        minipack = 0,
    },
    [1702158] = {
        id = 1702158,
        text = "비록 기모노가 비싸긴 하지만, 너를 위해서라면 망가트려도 괜찮아.",
        minipack = 0,
    },
    [1702159] = {
        id = 1702159,
        text = "여길 잡고, 힘을 줘서 당기면... 어...라...",
        minipack = 0,
    },
