    [1702395] = {
        id = 1702395,
        text = "알림",
        minipack = 0,
    },
    [1702396] = {
        id = 1702396,
        text = "이번에 수정하는 것은 모든 반환합니까?",
        minipack = 0,
    },
    [1702397] = {
        id = 1702397,
        text = "엄마, 여기 이상한 아저씨가 있어!",
        minipack = 0,
    },
    [1702398] = {
        id = 1702398,
        text = "쳇, 몸이 작아지니 정말 불편하잖네.",
        minipack = 0,
    },
    [1702399] = {
        id = 1702399,
        text = "화장실 가고 싶어. 혼자 못 가겠어.",
        minipack = 0,
    },
    [1702400] = {
        id = 1702400,
        text = "과자 먹고 싶어. 먹여 줘.",
        minipack = 0,
    },
    [1702401] = {
        id = 1702401,
        text = "치요가미입니다. 잘 부탁드려요.",
        minipack = 0,
    },
    [1702402] = {
        id = 1702402,
        text = "전 파파와 마마의 사랑의 결정체예요.",
        minipack = 0,
    },
    [1702403] = {
        id = 1702403,
        text = "파파, 이상한 일은 하지 말아 줘.",
        minipack = 0,
    },
    [1702404] = {
        id = 1702404,
        text = "3학년 A반",
        minipack = 0,
    },
    [1702405] = {
        id = 1702405,
        text = "이츠카 치요가미",
        minipack = 0,
    },
    [1702406] = {
        id = 1702406,
        text = "빈틈없는 인테리어라 해도 현관은 넓찍하게 설계하는 것이 좋다. 그것이 손님에 대한 예의이기 떄문이고, 현관은 때떄로 정령들과 '특별한 교감'이 이루어지는 장소이기도 하다.",
        minipack = 0,
    },
    [1702407] = {
        id = 1702407,
        text = "",
        minipack = 0,
    },
    [1702408] = {
        id = 1702408,
        text = "",
        minipack = 0,
    },
    [1702409] = {
        id = 1702409,
        text = "",
        minipack = 0,
    },
    [1702410] = {
        id = 1702410,
        text = "",
        minipack = 0,
    },
    [1702411] = {
        id = 1702411,
        text = "평범한 주택이네.이 각도가 괜찮다.",
        minipack = 0,
    },
    [1702412] = {
        id = 1702412,
        text = "",
        minipack = 0,
    },
    [1702413] = {
        id = 1702413,
        text = "",
        minipack = 0,
    },
    [1702414] = {
        id = 1702414,
        text = "",
        minipack = 0,
    },
    [1702415] = {
        id = 1702415,
        text = "",
        minipack = 0,
    },
    [1702416] = {
        id = 1702416,
        text = "정령 맨션을 지을 때, 코토리는 모든 정령들이 핑크빛 세계에 살기를 원했다. 그렇다면 그 도도한 쿠루미라고 해도 소녀 같은 면이 있지 않을까?(쿠루미가 이곳에 사는 일은 없겠지만 말이다)",
        minipack = 0,
    },
    [1702417] = {
        id = 1702417,
        text = "정령의 평소 생활을 지켜보고 싶다면, 정령 맨션의 거실을 돌아다니면 된다. 사소한 일에 그다지 신경을 쓰지 않는 정령들이 당신에게 멋진 모습을 보여줄지도 모르니 말이다.",
        minipack = 0,
    },
    [1702418] = {
        id = 1702418,
        text = "밤이 된 정령 맨션의 방, 정령들이 편안하게 잠에 드는 곳이다. 이곳에서는 텐구 시의 야경을 내려다볼 수 있어서, 정령들이 아름다운 꿈을 꾸며 잠들 수 있다.",
        minipack = 0,
    },
    [1702419] = {
        id = 1702419,
        text = "밤이 된 정령 맨션 거실, TV의 불빛이 아직 켜져 있다면, 분명히 요시농의 떠들썩한 목소리와 나츠미의 외침 소리를 들을 수 있을 것이다. 저녁에는 재미있는 드라마가 방영되기 때문이다.",
        minipack = 0,
    },
    [1702420] = {
        id = 1702420,
        text = "다과회 때는 아슬아슬했던 기억만 남았지만… 아니, 지금도 아슬아슬하다.",
        minipack = 0,
    },
    [1702421] = {
        id = 1702421,
        text = "",
        minipack = 0,
    },
    [1702422] = {
        id = 1702422,
        text = "밝고 아름다운 햇살도 정령들의 답답한 마음을 밝게 비추지는 못한다. 나 같은 당당한 정령이 어째서 얌전히 이곳에서 수업을 들어야 하는 거지? 정말 이상하다니까.",
        minipack = 0,
    },
    [1702423] = {
        id = 1702423,
        text = "텅 빈 옥상, 가끔씩 게으름을 피우는 학생들이 이곳에 모여 있다. 누군가 옥상에서 붉은색 옷차림의 신비한 소녀를 만난 적이 있다고 하는데, 그녀의 아름다운 얼굴은 도저히 잊을 수가 없었다고 한다.",
        minipack = 0,
    },
    [1702424] = {
        id = 1702424,
        text = "벌을 서 있던 경험을 떠올리게 만드는 교실의 복도, 수업 시간이 끝나면 시끌벅적하게 변한다. 아름다운 시간들은 이곳에서부터 서서히 사라지는 법이다...",
        minipack = 0,
    },
    [221001] = {
        id = 221001,
        text = "데이트 데이터가 존재하지 않습니다.",
        minipack = 0,
    },
    [1702426] = {
        id = 1702426,
        text = "이곳은 달을 감상하기 가장 좋은 곳이다. 하지만 밤에 전망대에 오는 사람들은 많지 않다. 만약 이곳에서 한 외로운 소녀의 모습을 본다고 해도, 그리 놀라지 않는 것이 좋다.",
        minipack = 0,
    },
    [1702427] = {
        id = 1702427,
        text = "밤이 된 학교의 복도는 무척이나 고요한 곳이다. 하지만 데이트 장소로는 적절하지 않은 것 같다. 오직 특별한 정령만이 이런 곳에 오는 것을 즐길 것이다.",
        minipack = 0,
    },
