    [1702461] = {
        id = 1702461,
        text = "",
        minipack = 0,
    },
    [1702462] = {
        id = 1702462,
        text = "정교한 장식으로 채워져 있고, 예술적인 분위기가 느껴지는 꽃집이다. 여자애들은 저마다 다른 꽃을 좋아하니, 다양한 꽃이 있는 꽃집은 데이트 장소로 매우 적합하다.",
        minipack = 0,
    },
    [1702463] = {
        id = 1702463,
        text = "정령을 공략하면서 지쳤을 때는 드링크바에 앉아 아이스초코 한 잔을 마시면 정령의 기분도 좋아지고, 당신의 체력도 빠르게 회복될 것이다.",
        minipack = 0,
    },
    [1702464] = {
        id = 1702464,
        text = "향기로운 꽃들이 있는 저녁의 꽃집에는 종종 나비가 날아든다. 조명 아래의 찬란한 꽃들은 반드시 데이트에 좋은 경험을 선사할 것이다.",
        minipack = 0,
    },
    [221006] = {
        id = 221006,
        text = "데이터 사용 불가",
        minipack = 0,
    },
    [1702466] = {
        id = 1702466,
        text = "상쾌한 밤바람을 느끼며 사랑하는 연인과 함께 시원한 음료를 마시는 행복한 장면, 분명 하루의 피로를 순식간에 없애줄 것이다. 그런 점에서 저녁의 드링크바는 최고의 선택이다.",
        minipack = 0,
    },
    [1702467] = {
