    [1702472] = {
        id = 1702472,
        text = "",
        minipack = 0,
    },
    [221007] = {
        id = 221007,
        text = "이전 스크립트 사용 불가",
        minipack = 0,
    },
    [1702474] = {
        id = 1702474,
        text = "사실 나는 대관람차를 타고 싶었지만, 롤러코스터도 나쁘지 않고, 워터 슬라이드도 괜찮다.",
        minipack = 0,
    },
    [1702475] = {
        id = 1702475,
        text = "어서 도망쳐! 경비원 아저씨가 나타났어!",
        minipack = 0,
    },
    [1702476] = {
        id = 1702476,
