        text = "",
        minipack = 0,
    },
    [1702480] = {
        id = 1702480,
        text = "남국의 풍경.",
        minipack = 0,
    },
    [221008] = {
        id = 221008,
        text = "이후 스크립트 사용 불가",
        minipack = 0,
    },
    [1702482] = {
        id = 1702482,
        text = "밤의 모래사장에서 산책하는 건 조금만 생각해 봐도 무척 낭만적인 일이지.",
        minipack = 0,
    },
    [1702483] = {
        id = 1702483,
        text = "담력 테스트? 나, 난 관심 없어. 관심 없다고... 지, 진짜로 관심 없다니까—— 으악!",
        minipack = 0,
    },
    [1702484] = {
        id = 1702484,
        text = "",
        minipack = 0,
    },
    [1702485] = {
        id = 1702485,
        text = "온천 개방을 준비하고 있습니다. 잠시만 기다려 주세요.",
        minipack = 0,
    },
    [1702486] = {
        id = 1702486,
        text = "온천욕을 즐기며 시원한 콜라 한 잔을 마시면 인생의 즐거움이 따로 없지. 하! 어디서 이런 아저씨가!",
        minipack = 0,
    },
    [1702487] = {
        id = 1702487,
        text = "",
        minipack = 0,
    },
    [1702488] = {
        id = 1702488,
        text = "",
        minipack = 0,
    },
    [221009] = {
        id = 221009,
        text = "아이템 부족",
        minipack = 0,
    },
    [1702490] = {
        id = 1702490,
        text = "주변 사람들은 모두 친절하고, 지나가는 사람들도 당신을 향해 미소를 지어 준다.",
        minipack = 0,
    },
    [1702491] = {
        id = 1702491,
        text = "도시의 교외는 인기가 많은 곳이다. 어떤 계절이든 마음이 탁 트이는 기분을 준다.",
        minipack = 0,
    },
    [1702492] = {
        id = 1702492,
        text = "여기가 명장면이다. 울타리 위에 ‘믿거나 넘기지 마시오’라는 표어를 썼다. 안전에 주의하세요.",
        minipack = 0,
    },
    [1702493] = {
        id = 1702493,
        text = "이런 석양 아래에서 잠깐 눈을 붙이면 정말 편안하다.",
        minipack = 0,
    },
    [1702494] = {
        id = 1702494,
        text = "",
        minipack = 0,
    },
    [1702495] = {
        id = 1702495,
        text = "만약 누군가가 핸드폰을 보면서 길을 걷고 있다면, 한번 놀라게 해주는 것도 좋다. 물론 농담이다. 다른 사람들과 부딪히지 않도록 조심해야 한다.",
        minipack = 0,
    },
    [1702496] = {
        id = 1702496,
        text = "가끔은 혼자 이곳에 와서 그네를 타고 싶어질 때가 있다.",
        minipack = 0,
    },
    [221010] = {
        id = 221010,
        text = "기능 미개방",
        minipack = 0,
    },
    [1702498] = {
