    [221011] = {
        id = 221011,
        text = "파일 사용 불가",
        minipack = 0,
    },
    [1702506] = {
        id = 1702506,
        text = "마유리와 요시노는 항상 이곳에 대해 궁금해 하는 것 같아. 조금 더 주위를 둘러볼까?",
        minipack = 0,
    },
    [1702507] = {
        id = 1702507,
        text = "",
        minipack = 0,
    },
    [1702508] = {
        id = 1702508,
        text = "문을 나서면 반드시 지나게 되는 곳이다. 딱히 특별한 추억 같은 건 없지만, 그래도 한 장 찍어 두자.",
        minipack = 0,
    },
    [1702509] = {
        id = 1702509,
        text = "이곳은 정말 조용하다. 하지만 가끔씩 비행기가 날아다니는 소리가 나는데, 정작 비행기는 보이지 않는다.",
        minipack = 0,
    },
