    [1702600] = {
        id = 1702600,
        text = "포잉! 포잉! 나는 캥거루! 포잉! 나는 캥거루!",
        minipack = 0,
    },
    [1702601] = {
        id = 1702601,
        text = "야호! 나는 이 게임의 메인 히로인, 주인공 중의 주인공 넵튠이야! 잘 부탁해!",
