        text = "그 일 후로,",
        minipack = 0,
    },
    [11000560] = {
        id = 11000560,
        text = "이것은 제가 당신을 위해 게임할 시간까지 포기해 가면서 만든 초콜릿이에요.",
        minipack = 0,
    },
    [11000568] = {
        id = 11000568,
        text = "새로운 한 해에 당신과의 새로운 만남이 기대해요.",
        minipack = 0,
    },
    [11000576] = {
        id = 11000576,
        text = "당신과 함께 있으면 시간이 더욱 빨리 가는 것 같아요.",
        minipack = 0,
    },
    [11000584] = {
        id = 11000584,
        text = "오오! 이, 이건 정말 맛있구나...",
        minipack = 0,
    },
    [11000592] = {
        id = 11000592,
        text = "아니에요.... 괜찮습니다. 당신에게 쓰러진다 해도, 기꺼이 원하던 바예요.",
        minipack = 0,
    },
    [262007] = {
        id = 262007,
        text = "제작",
        minipack = 0,
    },
    [11000608] = {
        id = 11000608,
        text = "또 만났네요",
        minipack = 0,
    },
    [11000616] = {
        id = 11000616,
        text = "온, 온천?! 옷을 벗어야 하나? 잠깐, 내가 뭘 부끄러워하는 거야",
        minipack = 0,
    },
    [11000624] = {
        id = 11000624,
        text = "아앗! 다들 반짝반짝 빛나고 있어. 나랑 아무 상관이 없지만...",
        minipack = 0,
    },
    [11000632] = {
        id = 11000632,
        text = "나랑 아무 상관이 없지만...",
        minipack = 0,
    },
    [11000640] = {
        id = 11000640,
        text = "응?....... 잠, 잠깐! 그런 수치스러운 대사를, 입, 입에 담을 수 있다니....... 이런 건 이제 금지이니라!",
        minipack = 0,
    },
    [11000648] = {
        id = 11000648,
