        text = "[잔월파공] 1%의 확률로 이번 피해의 50%에 해당하는 고정 피해를 입힌다. 해당 효과는 1초의 쿨타임이 적용된다",
        minipack = 0,
    },
    [11221405] = {
        id = 11221405,
        text = "[산 뽑기] 기술이 정령에게 입히는 피해가 6% 증가",
        minipack = 0,
    },
    [11221413] = {
        id = 11221413,
        text = "[산 뽑기] 명중 시 10%의 확률로 8초 동안 자신의 공격력이 5% 증가한다. 최대 3단계 중첩 가능하며, 중첩할 때마다 시간이 초기화된다",
        minipack = 0,
    },
    [11221421] = {
        id = 11221421,
        text = "[산 뽑기] 기술 피해 6% 증가",
        minipack = 0,
    },
    [11221429] = {
        id = 11221429,
        text = "[태양 뚫는 무지개] 크리티컬 확률 3% 증가",
        minipack = 0,
    },
    [11221437] = {
        id = 11221437,
        text = "[태양 뚫는 무지개] 기술 명중 시 5%의 확률로 적의 방어를 5초 동안 5% 감소시킨다. 최대 3단계 중첩 가능하며, 중첩할 때마다 시간이 초기화된다",
        minipack = 0,
    },
    [11221445] = {
        id = 11221445,
        text = "[태양 뚫는 무지개] 크리티컬 피해 5% 증가",
        minipack = 0,
    },
    [11221453] = {
        id = 11221453,
        text = "[위치 에너지] 레벨이 0보다 높을 시 위치 에너지 레벨에 따라 2초마다 주변에게 자신의 공격력의 100%/150%200%에 해당하는 고정 피해를 입힌다.",
        minipack = 0,
    },
    [11221461] = {
        id = 11221461,
        text = "관통 피해를 입힐 때마다 5초 동안 자신 크리티컬 확률이 4% 증가한다. 최대 5단계 중첩 가능하며, 중첩할 때마다 시간이 초기화된다",
        minipack = 0,
    },
    [492001] = {
        id = 492001,
        text = "자동 회수된 재료",
        minipack = 0,
    },
    [492002] = {
        id = 492002,
        text = "확인 시 세련 재료를 소모하며, 해당 재료의 %s 강화 자원을 반환합니다.",
        minipack = 0,
    },
    [213236] = {
        id = 213236,
        text = "\"로키 파밀리아\" 소속 최강의 Level 6 모험가. \"검희\"로 불리며 이름이 널리 알려졌다.",
        minipack = 0,
    },
    [246004] = {
        id = 246004,
        text = "거점이 존재하지 않습니다!",
        minipack = 0,
    },
    [63550] = {
        id = 63550,
        text = "계약 포인트 분배는 피해, 생존, 균형 3가지 분류로 구성되며, 각 분류의 일부 속성은 자유롭게 선택할 수 있습니다.",
        minipack = 0,
    },
    [213237] = {
        id = 213237,
        text = "금일 남은 횟수 %d",
        minipack = 0,
    },
    [246005] = {
        id = 246005,
        text = "최대 3개의 캐릭터 출전 가능",
        minipack = 0,
    },
    [213238] = {
        id = 213238,
        text = "몸에 파란색 영장을 두르고, 손에 긴 무기를 쥔챈로, 평범한 준정령과의 전투 중에서도 일격에 적을 과자처럼 박살 낼 수 있다.",
        minipack = 0,
    },
    [246006] = {
        id = 246006,
        text = "최대 1개의 지원 캐릭터 출전 가능",
        minipack = 0,
    },
    [213239] = {
        id = 213239,
        text = "<지배자 Ruler> 소노가미 린네, 천사는 흉화낙원이며, 린네는 이 힘으로 초범위 결계를 만들 수 있다.",
        minipack = 0,
    },
    [2101002] = {
        id = 2101002,
        text = "상점",
        minipack = 0,
    },
    [246007] = {
        id = 246007,
        text = "빌려온 지원 캐릭터 데이터 에러, 파티를 다시 편집하세요",
        minipack = 0,
    },
    [2101006] = {
        id = 2101006,
        text = "수집",
        minipack = 0,
    },
    [2101008] = {
        id = 2101008,
        text = "보유",
        minipack = 0,
    },
    [2101010] = {
        id = 2101010,
        text = "스테이지 보상",
        minipack = 0,
    },
    [2101012] = {
        id = 2101012,
        text = "입장",
        minipack = 0,
    },
    [2101014] = {
        id = 2101014,
        text = "2. 스테이지에 진입하려면 아이템 [신비한 USB]을 소모해야 합니다. 스테이지 해금 후에는 아이템이 소모되지 않으며 무제한으로 입장할 수 있습니다. 신비한 USB는 일일 출석을 통해 획득할 수 있습니다.",
        minipack = 0,
    },
    [2101016] = {
        id = 2101016,
        text = "4. 스테이지 중 탐색도 100% 수집 퀘스트를 완료하면 업적 보상을 수령할 수 있습니다.",
        minipack = 0,
    },
    [2101018] = {
        id = 2101018,
        text = "6. 맵에서 획득하는 [직원 이름표]를 수집하면 보상으로 교환할 수 있습니다. 맵마다 5개가 있으니 잊지 마세요!",
        minipack = 0,
    },
    [246008] = {
        id = 246008,
        text = "지원 캐릭터를 설정하지 않았습니다!",
        minipack = 0,
