    },
    [2101084] = {
        id = 2101084,
        text = "사물함 안에는 책이 가지런하게 놓여있었다. <C++ 입문부터 포기까지>랑… 그냥 그만 알아보자.",
        minipack = 0,
    },
    [2101086] = {
        id = 2101086,
        text = "사물함 안쪽에는 비뚤비뚤한 바를 [정] 자가 다섯 개 쓰여있었다. 그 밑에 쓰인 문구는- 지금까지 떨어진 머리카락 수.",
        minipack = 0,
    },
    [2101088] = {
        id = 2101088,
        text = "수납장 안의 보온병에는 구기자로 가득 차 있다. 그리고 어째서 옆에 청진기가 하나 있다?",
        minipack = 0,
    },
    [2101090] = {
        id = 2101090,
        text = "수납장안에 한 박스의 샴푸가 있을 줄은. 패왕 샴푸… 어디서 들어본거 같은데?",
        minipack = 0,
    },
    [2101092] = {
        id = 2101092,
        text = "수납장에 문을 여는 주문이 쓰여있다- 암흑의 힘을 지닌 열쇠여! 진정한 모습으로 내 앞에 나타나라 너와의 계약에 따라 장이 명한다, 봉인해제!",
        minipack = 0,
    },
    [2101094] = {
        id = 2101094,
        text = "프로그래머의 메모지: 이번 설날에는 나의 와이프 토카랑 아키바에 가야지.",
        minipack = 0,
    },
    [2101096] = {
        id = 2101096,
        text = "아령, 프로테인 등으로 가득 차고 반쪽짜리 바나나가 들어있다.",
        minipack = 0,
    },
    [2101098] = {
        id = 2101098,
        text = "프로그래머가 사무실에서 신는 슬리퍼가 들어있다. 기묘한… 향기가 난다! 어째서!?",
        minipack = 0,
    },
    [2101100] = {
        id = 2101100,
        text = "야근을 위한 세면도구가 깔끔하게 정리되어있다. 마스크팩이랑 스킨케어도 있다니.",
        minipack = 0,
    },
    [2101102] = {
        id = 2101102,
        text = "러브레터로 보인다. 위에는 이렇게 쓰여있다- 1001개의 연애 상대를 만들 거다.",
        minipack = 0,
    },
    [2101104] = {
        id = 2101104,
        text = "연도가 오래된 게임팩. 파란색 정장의 고슴도치 머리 남자가 그려져 있다. 당당한 기세로 손가락을 어딘가를 가리키고 있다.",
        minipack = 0,
    },
    [2101106] = {
        id = 2101106,
        text = "쪽지에는 이렇게 쓰여있다- 잠수함 패치 안 했다. 정말로 안 했다. 맹세컨데 안 했다…",
        minipack = 0,
    },
    [2101108] = {
        id = 2101108,
        text = "이상한 포즈를 취한 남자의 피규어가 들어있다. 이러한 문구가 적혀있다- [나는 닝겐을 그만두겠다!]",
        minipack = 0,
    },
    [2101110] = {
        id = 2101110,
        text = "일기장의 구석에는 이렇게 쓰여있다- X월 X일. 날씨 맑음. 사건: 유저가 버그를 5개나 찾아냈다. 해결 방안: 기획 둘을 잡아다가 하늘에 제사를 지냈다.",
        minipack = 0,
    },
    [2101112] = {
        id = 2101112,
        text = "구겨진 핑크색 쪽지: 프로그래머 행님… 부탁이 딱 하나 있는데 들어주실 수 있을까요?",
        minipack = 0,
    },
    [2101114] = {
        id = 2101114,
        text = "책의 향기가 얼굴에 덮어온다. 데이트 어 라이브 오피셜 소설집으로 빼곡 빼곡 가득 차있다.",
        minipack = 0,
    },
    [2101116] = {
        id = 2101116,
        text = "사용하지 않은 영화표가 두 장 들어있다. 날짜는 [2020.9.21]… (잠깐! 이거 게임 오픈베타 날짜 아니야?)",
        minipack = 0,
    },
    [2101118] = {
        id = 2101118,
        text = "데이트 어 라이브의 굿즈로 가득 차 있다. 사물함의 정중앙에는 '데오라가 더 잘 될 수 있길! '라고 적혀있다.",
        minipack = 0,
    },
    [2101120] = {
        id = 2101120,
        text = "코토리는 나의 와이프! 요시노는 나의 딸! ' 과 같은 구호가 잔뜩 붙어 있다.",
        minipack = 0,
    },
    [2101122] = {
        id = 2101122,
        text = "야근러들이 자주 시키는 파오후 세트에 딸려오는 치킨 할인권으로 가득 차 있으나 죄다 기간이 만료된 모양이다.",
        minipack = 0,
    },
    [2101124] = {
        id = 2101124,
        text = "포스터로 가득 찬 사물함. 중간에 있는 두 장은 오리가미의 포스터로 각각 [Angel]과 [Devil]이라고 적혀있다.",
        minipack = 0,
    },
    [2101126] = {
        id = 2101126,
        text = "현수막이 들어있다- 작붕은 절대 내 탓이 아니다!",
        minipack = 0,
    },
    [2101128] = {
        id = 2101128,
        text = "데이트 어 라이브 공식 굿즈로 꽉 차있다니. 피규어, 족자랑 등신대 다양하게 들어있다. (가져갈까?)",
        minipack = 0,
    },
    [2101130] = {
        id = 2101130,
        text = "사진이 들어 있는데 모 방송의 유명한 BJ의 싸인 사진인 듯?",
        minipack = 0,
    },
    [2101132] = {
        id = 2101132,
        text = "메모지가 들어있다. 빨간펜으로 [강 보스의 머리카락]이라고 쓰여있다. (무슨 암호인가?)",
        minipack = 0,
    },
    [2101134] = {
        id = 2101134,
        text = "일기장이 들어있다. 이미 사용한 패키지 암호 코드가 적혀있다. 선이 그어져 있지 않은 게 한 줄 있다- [핫게임 몸보신제]",
        minipack = 0,
    },
    [2101136] = {
        id = 2101136,
        text = "사물함의 안에는 혈서로 이런 게 쓰여있다- 그러니까 그 일러스트는 우리가 그린 게 아니라니까! [알아보고 때려주세요 ㅠㅠ]",
        minipack = 0,
    },
    [2101138] = {
        id = 2101138,
        text = "명단이 들어있다. 운영자가 외주를 맡길 일러스트레이터들의 명단으로 보인다.",
        minipack = 0,
    },
    [2101140] = {
        id = 2101140,
        text = "아주 정교하게 만들어진 금속 도색 건프라가 들어있다. (부자다)",
        minipack = 0,
    },
    [2101142] = {
        id = 2101142,
        text = "덕후 콜라로 가득 차 있을 줄이야. 옆에 있는 메모를 보아하니 이전의 애니 행사 때 남겨진 것들로 보인다.",
        minipack = 0,
    },
    [2101144] = {
        id = 2101144,
        text = "타블렛이 들어있다. 마모된 정도로 미뤄보아 꽤 오랫동안 사용한 것 같다.",
        minipack = 0,
    },
    [2101146] = {
        id = 2101146,
        text = "사물함 안에는 고 퀄리티의 모형들로 가득 차있다. 근데 전부 용이다?",
        minipack = 0,
    },
    [2101148] = {
        id = 2101148,
        text = "구기차를 담은 보온병. 중노년 사용자를 위한 디자인.",
        minipack = 0,
    },
    [2101150] = {
        id = 2101150,
        text = "아주 예쁜 로리타 드레스. 옆에는 설계안이 놓여있다. 디자인 담당자가 직접 만든 건가?",
        minipack = 0,
    },
    [2101152] = {
        id = 2101152,
        text = "디자인 담당자가 소장한 NC-17 책이 들어있다.",
        minipack = 0,
    },
    [2101154] = {
        id = 2101154,
