    [13200479] = {
        id = 13200479,
        text = "행운의 요시농이 오늘의 날씨 예보와 운세를 알려드립니다~",
        minipack = 0,
    },
    [13200487] = {
        id = 13200487,
        text = "오래된 버스 정거장, 더는 버스가 지나지 않지만, 길을 안내하는 표지판이 있습니다.",
