    },
    [13313358] = {
        id = 13313358,
        text = "흰색 개 부족의 강력한 종족 재능, 습득 후 전투 속성이 대폭 증가한다.",
        minipack = 0,
    },
    [13313366] = {
        id = 13313366,
        text = "견신족 전사는 천생적인 육식 동물이며, 고기를 먹는건 쿤타아에서 가장 추악한 죄가 되었다.",
        minipack = 0,
    },
    [13313374] = {
        id = 13313374,
        text = "미식에 대한 추구는 모든 대식묘족이 갈망하는 것이며, 그들의 공중함은 창고가 매우 넓다.",
        minipack = 0,
    },
    [1020531] = {
        id = 1020531,
        text = "이거, 이거 정말 맛있어!",
        minipack = 0,
    },
    [13313390] = {
        id = 13313390,
        text = "대식묘족은 선조의 염력을 이어받아, 주변의 자기력을 이용해 적의 공격을 교란할 수 있다.",
        minipack = 0,
    },
    [1020532] = {
        id = 1020532,
        text = "배가 파업하려고 해...",
        minipack = 0,
    },
    [13313406] = {
        id = 13313406,
        text = "거센 파도를 뚫으면서, 인어족은 비범한 육체와 영혼을 지녔다.",
        minipack = 0,
    },
    [1020533] = {
        id = 1020533,
        text = "음식이... 필요해...",
        minipack = 0,
    },
    [13313422] = {
        id = 13313422,
        text = "쿤타아의 핵심 구역에 곧 도착합니다. 붉은 개 부족의 전란을 가라앉혀야, 쿤타아에 평화가 찾아올 것입니다.",
        minipack = 0,
    },
    [13313430] = {
        id = 13313430,
        text = "위대한 쿤타아의 지식 창고, 비보 「문명의 열쇠」를 지닌 자만이 진정한 모습을 볼 수 있다고 합니다.",
        minipack = 0,
    },
    [13313438] = {
        id = 13313438,
        text = "아군 함대가 왕실 함대에 포위당했습니다. 즉시 지원하러 가세요.",
        minipack = 0,
    },
    [13313446] = {
        id = 13313446,
        text = "소금파 인접국의 '영원한 감옥' 앞에, 완전 무장한 거대 함선 「호랑이」가 출현했습니다. 전투를 피할 수 없을 것 같습니다.",
        minipack = 0,
    },
    [13313454] = {
        id = 13313454,
        text = "무너진 궁전은 메소포타아의 지나간 영광의 증거물이다. 잃어버린 보물 「반짝이는 고양이 눈」이 안에 묻어 있다.",
        minipack = 0,
    },
    [13313462] = {
        id = 13313462,
        text = "메소포타아 소금파 선봉함을 처치하고, 포위망 돌파구를 찾으세요.",
        minipack = 0,
    },
    [13313470] = {
        id = 13313470,
        text = "황실 함대의 포위망에서 벗어난 듯합니다만, 굉장히 빠른 속도의 함선 「돼지」가 앞길을 막아섰습니다.",
        minipack = 0,
    },
    [13313478] = {
        id = 13313478,
        text = "심해 깊숙한 곳에 있는 만상을 망라 신비의 장소, 그곳에서 비보 「해양 축소판」이 탄생한다.",
        minipack = 0,
    },
    [13313486] = {
        id = 13313486,
        text = "어인족 군단의 잔당이 반격을 준비하고 있습니다. 놈들의 함대를 뿌리째 뽑아버리세요.",
        minipack = 0,
    },
    [13313494] = {
        id = 13313494,
        text = "아틀란티스 하늘 해적의 본거지를 찾아내고, 섬멸 작전에 참여하세요!",
        minipack = 0,
    },
    [13313502] = {
        id = 13313502,
        text = "몇몇 적은 공중함 외곽에 달라붙을 수 있기 때문에, 자주 사람을 보내 순찰을 해야 합니다.",
