    [1452001] = {
        id = 1452001,
        text = "지금? 그럴 순 없어. 레이네가 아직 네 훈련 계획을 준비하지 못했으니까, 10레벨이 되면 다시 와.",
        minipack = 0,
    },
    [1452002] = {
        id = 1452002,
        text = "정령 소환? 잠깐만... 공간진을 일으킬 수도 있단 말이야! 적어도 1-3 스테이지는 클리어하고 난 뒤에 생각해!",
        minipack = 0,
    },
    [1452003] = {
        id = 1452003,
        text = "정령의 존재는 절대 기밀이야. 1-3 스테이지를 클리어해야 알려줄 수 있다고~",
        minipack = 0,
    },
    [1452004] = {
        id = 1452004,
        text = "바보 오빠, 죽고 싶은 거야? 지금의 힘으로 무슨 천사를 다루겠다는 거야. 9레벨이 된 후에 다시 와!",
        minipack = 0,
    },
    [1452005] = {
        id = 1452005,
        text = "세피라를 장착하겠다고? 1-5 스테이지를 클리어하고 다시 말해!",
        minipack = 0,
    },
    [1320936] = {
