        minipack = 0,
    },
    [1452007] = {
        id = 1452007,
        text = "기다려! 지금 거길 가는 건 너무 위험해. 15레벨이 된 후에 다시 생각해 봐.",
        minipack = 0,
    },
    [1320938] = {
        id = 1320938,
        text = "응원 9레벨 달성",
        minipack = 0,
    },
    [1452009] = {
        id = 1452009,
        text = "돈이 없는데 어떻게 상점엘 가겠다는 거야. 5레벨이 되면 자금을 줄게~",
        minipack = 0,
