        minipack = 0,
    },
    [1452013] = {
        id = 1452013,
        text = "정말 바보네. 라타토스크가 자금이 부족할 리가 없잖아. 용돈이 있으면... 주말에 나랑 맛있는 거 먹으러 가자.",
