    [1326433] = {
        id = 1326433,
        text = "1주년 축제 기념 칭호, 주년 축제 이벤트 참여 시 해당 칭호 획득 가능.",
        minipack = 0,
    },
    [1326434] = {
        id = 1326434,
        text = "검희의 질주 여정 이벤트에서 랭킹 501-1000위 달성 시 획득할 수 있는 칭호. 장착 시 던만추 콜라보 이벤트 스테이지에서 2%의 드랍률 보너스 획득.",
        minipack = 0,
    },
    [1326435] = {
