    [11303038] = {
        id = 11303038,
        text = "[뇌폭] 크리티컬 확률 3% 증가",
        minipack = 0,
    },
    [11303046] = {
        id = 11303046,
        text = "[뇌폭] 스킬 쿨타임 -1초.",
        minipack = 0,
    },
    [11303054] = {
        id = 11303054,
        text = "[성역] 나타나기 전에 에너지 선풍을 일으켜 주변의 적을 끌어모은다. 스킬은 총 공격력의 1600%만큼 피해를 입힌다.",
        minipack = 0,
    },
    [11303062] = {
        id = 11303062,
        text = "[성역] 종료시 에너지 폭발 발동. 스킬은 총 공격력의 2000%만큼 피해를 입힌다.",
        minipack = 0,
    },
    [11303070] = {
        id = 11303070,
        text = "[성역] 사용 후 8초 동안 자신의 공격력 8% 증가",
        minipack = 0,
    },
    [11303078] = {
        id = 11303078,
        text = "[신벌] 에너지 공격 빈도가 빨라지고 공격 횟수가 증가한다. 스킬은 총 공격력의 1600%만큼 피해를 입힌다.",
        minipack = 0,
    },
    [11303086] = {
        id = 11303086,
        text = "[신벌] 피해 20% 증가",
        minipack = 0,
    },
    [11303094] = {
        id = 11303094,
        text = "[신벌] 스킬 쿨타임 3초 감소",
        minipack = 0,
    },
    [11303102] = {
        id = 11303102,
        text = "[신벌] 크리티컬 피해 32% 증가",
        minipack = 0,
    },
    [11303110] = {
        id = 11303110,
        text = "마유리가 처치한 적은 20%의 확률로 뇌전 구슬로 변한다. 뇌전 구슬은 마유리의 50%만큼의 공격력과 20%만큼의 최대 HP를 가진다. 6초 동안 지속, 동시에 최대로 6개의 뇌전 구슬이 존재할 수 있다.",
        minipack = 0,
    },
    [11303118] = {
        id = 11303118,
        text = "파티원이 빈사 상태 시 3초 동안 무적 효과를 획득하게 되고 3초 내에 30%의 HP를 회복하며 마유리가 소형 [신벌] 스킬을 한 번 발동한다. 큰 범위 내의 적에게 4회의 공격을 가하여 발동자 공격력의 400%만큼 피해를 입힌다. 해당 효과는 소환물에게 적용되지 않는다. 스킬 쿨타임 120초.",
        minipack = 0,
    },
