    [10603033] = {
        id = 10603033,
        text = "[뇌전광인] 스킬 쿨타임 -0.5초.",
        minipack = 0,
    },
    [10603041] = {
        id = 10603041,
        text = "[뇌전광인] 보호막이 적용 된 목표 명중 시 해당 목표에게 이번 피해의 10%만큼을 추가 피해로 입힌다.",
        minipack = 0,
    },
    [10603049] = {
        id = 10603049,
        text = "[뇌전광인] 스킬 명중률 +5%, 크리티컬 확률 +2%.",
        minipack = 0,
    },
    [10603057] = {
        id = 10603057,
        text = "[구름 그림자] 추가로 관통을 1회 진행한다. \n적에게 공격력의 220%에 해당하는 뇌전 피해를 4회에 거쳐 입힌다.",
        minipack = 0,
    },
    [10603065] = {
        id = 10603065,
        text = "[구름 그림자] 목표 명중 시 6초 동안 대상의 방어력 -25%, 중첩 불가.",
        minipack = 0,
    },
    [10603073] = {
        id = 10603073,
        text = "[구름 그림자] 레이저 발사선 지속시간 증가. \n적에게 공격력의 675%에 해당하는 뇌전 피해를 11회에 거쳐 입힌다.",
        minipack = 0,
    },
    [10603081] = {
        id = 10603081,
        text = "[성역 빛날] 레이저가 전방을 관통한다. \n적에게 공격력의 371%에 해당하는 뇌전 피해를 7회에 거쳐 입힌다.",
        minipack = 0,
    },
    [10603089] = {
        id = 10603089,
        text = "[성역 빛날] 스킬 관통률 +3%.",
        minipack = 0,
    },
    [10603097] = {
        id = 10603097,
        text = "[성역 빛날] 레이저 발사선이 육망성을 형성하며 격렬한 폭발을 1회 일으킨다. \n적에게 공격력의 400%에 해당하는 뇌전 피해를 10회에 거쳐 입힌다.",
        minipack = 0,
    },
    [10603105] = {
        id = 10603105,
        text = "감전된 목표 사망시 폭발을 1회 일으키며 폭발 범위 내의 적에게 감전 효과를 적용한다. \n[설명: 감전된 목표가 공격 받을 때 추가로 마나의 공격력의 20% 만큼 뇌전 피해를 받는다.",
