    },
    [300731] = {
        id = 300731,
        text = "비스트-범용 A형",
        minipack = 0,
    },
    [14210210] = {
        id = 14210210,
        text = "세상에서 가장 무서운 일은 자아의 침식이 아니라, 잊혀져 무한한 공허 속으로 빠져드는 것이다. 물에 빠진 사람의 늘어트린 두 손을 누가 잡아줄 수 있을까.",
        minipack = 0,
    },
    [14210218] = {
        id = 14210218,
        text = "수학여행 중 나타난 쌍둥이 자매 야마이 카구야와 야마이 유즈루, 최강자의 이름을 건 결투가 이제 시작된다! —— '어디 덤벼 보라고!'",
        minipack = 0,
    },
    [14210226] = {
        id = 14210226,
        text = "클리포트의 나무 개방, 작전 목표 확인, 마왕 - 루키프구스 처치. 세피라 세계를 정화하라!",
        minipack = 0,
    },
    [300732] = {
        id = 300732,
        text = "DEM 진압대원",
        minipack = 0,
    },
    [14210242] = {
        id = 14210242,
        text = "결전 개시. 케루비엘 최종 페이즈, 전투의 불길이 모든 것을 불태운다.",
        minipack = 0,
    },
    [14210250] = {
        id = 14210250,
        text = "3기 신규 정령 나츠미 등장! —— '너도 귀찮은 짓을 하러 온 거야? 그럼 날 탓하진 말라고.'",
        minipack = 0,
    },
    [14210258] = {
        id = 14210258,
