    [13310504] = {
        id = 13310504,
        text = "추억 파편5",
        minipack = 0,
    },
    [13310512] = {
        id = 13310512,
        text = "형태가 기괴한 파편, 안에는 뭔가 영상 같은 것이 움직이고 있다. 모든 파편 수집 시 소장 CG를 활성화할 수 있다.",
        minipack = 0,
    },
    [13310520] = {
        id = 13310520,
        text = "형태가 기괴한 파편, 안에는 뭔가 영상 같은 것이 움직이고 있다. 모든 파편 수집 시 소장 CG를 활성화할 수 있다.",
        minipack = 0,
    },
    [13310528] = {
        id = 13310528,
        text = "친애하는 서약자님: \n 데이트 어 라이브와 핫게임 스튜디오에 대한 성원에 감사드립니다. 여러분 덕분에 정령들이 여러분과 함께하는 새로운 봄을 맞이하게 되었습니다. \n 여러분의 성원 덕분에 지금까지 계속해서 게임이 성장할 수 있었습니다. 핫게임 스튜디오도 앞으로 계속해서 노력을 거듭할 것입니다.\n 그럼, 우리들의 전쟁은 계속됩니다!\n 핫게임 스튜디오",
        minipack = 0,
    },
    [13310536] = {
        id = 13310536,
        text = "",
        minipack = 0,
    },
    [13310544] = {
        id = 13310544,
        text = "친애하는 서약자님: \n <데이트 어 라이브: 다시 만난 정령>이 여러분의 성원 덕분에 1주년 생일을 맞이하게 되었습니다. 항상 함께해 주셔서 감사합니다. \n 지난 1년간, 데이트 어 라이브는 당신과 함께 모진 비바람을 견뎠습니다. \n 지난 1년간, 데이트 어 라이브는 당신 덕분에 용감하게 도전할 수 있었습니다. \n 지난 1년간, 우리는 온 마음을 다해 우리들의 이야기를 써 내려갔습니다. \n 앞으로도 함께 더욱 행복한 추억을 만들 수 있길 바랍니다. \n 앞으로도 더욱 즐거운 일들이 가득할 수 있도록 노력할 것을 다짐합니다. \n 그럼, 우리들의 전쟁은 계속됩니다!",
        minipack = 0,
    },
    [13310552] = {
        id = 13310552,
        text = "토비이치 오리가미에게 나와 사귀어 달라고 말한다면, 그녀는 어떻게 답할까...?",
        minipack = 0,
    },
    [13310560] = {
        id = 13310560,
        text = "어째서 메이드복을 사는 일을 내가 맡아야 하는 거야... 그런 건 전혀 모르는데!",
        minipack = 0,
    },
    [13310568] = {
        id = 13310568,
        text = "코토리가 어째서 강해진 건지 줄곧 궁금했다. 그녀가 이 바보 오빠를 지키기 위해서라고 말하기 전까지...",
        minipack = 0,
    },
    [13310576] = {
        id = 13310576,
        text = "내게 전화를 걸어 카페에서 만나자고 한 코토리, 내 꿈을 이루어주기 위해서라니?",
        minipack = 0,
    },
    [13310584] = {
        id = 13310584,
        text = "섹시한 바니걸 복장을 입은 나츠미는 이번 카니발의 주인이라고!",
        minipack = 0,
    },
    [13310592] = {
