    [26020] = {
        id = 26020,
        text = "라타토스크에서 수집한 영력으로 구성한 중합 수정석, 비교적 많은 영력이 함유되어 있다. 정령의 신물 레벨 강화에 사용한다.",
        minipack = 0,
