        minipack = 0,
    },
    [16000207] = {
        id = 16000207,
        text = "5. 동아리 순위 보상은 순위에 진입한 동아리에게만 지급되며, 그중 최소 1회 도전에 참여하고 피해를 입힌 동아리 구성원만 보상을 획득할 수 있습니다",
        minipack = 0,
