    [10203016] = {
        id = 10203016,
        text = "[AST 제식 광검] 5단 연속 공격 가능.\n5단： 적에게 공격력 200%만큼 화염 피해를 1회 입힌다.",
        minipack = 0,
    },
    [10203024] = {
        id = 10203024,
        text = "[AST 제식 광검] 매 단계 공격범위 +20%.",
        minipack = 0,
