    [10203056] = {
        id = 10203056,
        text = "[극한 사격] 개틀링 기관총 탄환 발사 횟수 12회로 증가. \n매번 적에게 공격력 41%만큼 화염 피해 입힌다.",
        minipack = 0,
    },
    [27098] = {
        id = 27098,
        text = "메이드 카페 전속 신물. 개량 메이드복. 청색 백색의 조합에 큰 사이즈의 리본으로 취향 저격!",
        minipack = 0,
    },
    [28122] = {
        id = 28122,
        text = "[카발라]의 세피라 세계에서 등장하는 생명의 정수와 악마 표식을 통해 카발라 상점에서 아이템과 교환할 수 있습니다.",
        minipack = 0,
    },
    [10203080] = {
        id = 10203080,
        text = "[핵평사자] 스킬 피해 +20%.",
        minipack = 0,
    },
    [10203088] = {
        id = 10203088,
        text = "[핵평사자] 내성 소모 -2.",
        minipack = 0,
    },
    [10203096] = {
        id = 10203096,
        text = "[핵평사자] 목표 명중 시 15%의 확률로 적을 3초 동안 스턴시킨다.",
        minipack = 0,
    },
    [32218] = {
        id = 32218,
        text = "라스테이션의 수호 여신, 흑발의 트윈 테일의 노력파 소녀, 하지만 성격은 솔직하지 못하다",
        minipack = 0,
