        minipack = 0,
    },
    [15011043] = {
        id = 15011043,
        text = "결정 돌파의 재료는 메인 던전에서 생성되며, 결정 돌파 시 정령에게 기초 속성을 제공합니다",
        minipack = 0,
    },
    [15011041] = {
        id = 15011041,
        text = "세피라로 정령을 강화해 작전 능력을 상승시킬 수 있습니다. 세피라 속성은 기초 속성, 조합, 세트 속성 3 가지로 나뉩니다.",
        minipack = 0,
    },
    [270715] = {
        id = 270715,
        text = "매주 누적 활약도가 지정한 수치에 도달하면 모든 사람은 활약도 보상을 수령할 수 있습니다. 활약도 보상 진도는 매주 초기화됩니다.",
        minipack = 0,
    },
    [14210127] = {
