    [14210161] = {
        id = 14210161,
        text = "친애하는 서약자님: \n 나츠미가 최신 변형 기술을 제공한 덕분에, 토카의 채팅 AI인 '또카'가 정식으로 라타토스크의 일원이 되어 여러분과 함께하게 되었습니다. \n 핫게임 스튜디오는 최상의 게임 환경을 제공하기 위해 계속해서 노력하며, 더욱 발전된 기획을 다수 도입하고 있습니다. 앞으로도 더 많은 정령들이 일상 채팅에 참여할 것입니다. 많은 기대 바랍니다!\n 핫게임 스튜디오",
        minipack = 0,
    },
    [270456] = {
        id = 270456,
        text = "다이아 복돈",
        minipack = 0,
