    [13312001] = {
        id = 13312001,
        text = "카드 한 장을 뒤집는다. 동일한 카드를 뒤집을 시 해당하는 보상을 획득한다.",
        minipack = 0,
    },
    [13312009] = {
        id = 13312009,
        text = "위험천만한 이세계 깊숙한 곳에서 얻은 휘장, 인지를 초월한 강력한 힘을 지니고 있으며, 개인 응원 포인트와 자신의 동아리 응원 포인트를 수집할 수 있다.(동아리 포인트는 동아리 가입 24시간 후에 증가 가능).",
