    },
    [13400226] = {
        id = 13400226,
        text = "지옥훈련",
        minipack = 0,
    },
    [13400201] = {
        id = 13400201,
        text = "근처 고등학교에 다니고 있는 아르바이트생 메이드인 듯하다. 경험이 부족하지만 부지런하고 열정적이다.",
        minipack = 0,
    },
    [13400200] = {
        id = 13400200,
        text = "몸매가 늘씬한 푸른색 머리의 메이드. 연예인에게도 밀리지 않는 귀여운 외모로 높은 인기를 거느리고 있다. 그럼에도 자신도 모르게 한숨을 쉬곤 한다.",
        minipack = 0,
    },
    [13400199] = {
        id = 13400199,
        text = "사람들 앞에 모습을 잘 드러내지 않는 귀여운 메이드. 저녁 8시에 있는 마술쇼는 카페의 하이라이트이다.",
        minipack = 0,
    },
    [13400198] = {
        id = 13400198,
        text = "가만히 서 있으면 도자기 인형처럼 보일 정도로 낯선 손님에게 말을 거는 일이 없다.",
        minipack = 0,
    },
    [13400197] = {
        id = 13400197,
        text = "어딘가 멍~하고 뭘 해야 할지 모르지만 귀여운 외모로 모두의 사랑을 한몸에 받고 있다.",
        minipack = 0,
    },
    [13400196] = {
        id = 13400196,
        text = "달콤한 노랫소리를 가진 아이돌 기질의 아이돌 메이드. 허나 남성 고객을 상당히 거부한다.",
        minipack = 0,
    },
    [13400195] = {
        id = 13400195,
        text = "메이드의 일에 대해서라면 누구한테도 지지 않는 소녀. 필살기는 모든 요리를 어둠의 요리로 만드는 것.",
        minipack = 0,
    },
    [13400194] = {
        id = 13400194,
        text = "메이드의 일에 아주 섬세한 소녀. 모든 것을 질서정연하게 처리하고 싶으나 그건 어디까지나 희망 사항…",
        minipack = 0,
    },
    [13400193] = {
        id = 13400193,
        text = "모든 것을 관리하는 점장급 메이드. 다른 메이드에게 일을 시키거나 가끔은 애교를 부린다.",
        minipack = 0,
    },
    [13400192] = {
        id = 13400192,
        text = "나이트메어와 같은 눈빛을 가졌고 살기를 내뿜는 찬 메이드. 아름다운 외모의 소유자이지만 함부로 다가갔다간 큰코다칠지도 모른다.",
        minipack = 0,
    },
    [13400191] = {
        id = 13400191,
        text = "연애에 대해서라면 모르는 게 없는 메이드. 아주 적극적인 성격은 남을 어쩔 줄 모르게 한다.",
        minipack = 0,
    },
    [13400190] = {
        id = 13400190,
        text = "카페에서 가장 인기 있는 메이드. 사고뭉치지만 하도 귀여워서 언제나 용서를 받는다.",
        minipack = 0,
    },
    [13400189] = {
        id = 13400189,
        text = "기가 센 금발 메이드. 손님에게 꾸중을 당하면 어쩔 줄 모른다. 때때로는 무서울 정도의 위압감을 낸다.",
        minipack = 0,
    },
    [13400188] = {
        id = 13400188,
        text = "남을 가지고 장난치는 걸 좋아하는 두꺼운 안경을 쓴 메이드. 그녀를 화나게 하면 뒤통수를 조심해야 할 것이다.",
        minipack = 0,
    },
    [13400187] = {
        id = 13400187,
        text = "청순한 외모의 단발 메이드. 어쩌다 까칠하게 굴어도 신경 쓰지 마시길.",
        minipack = 0,
    },
    [13400186] = {
        id = 13400186,
        text = "포니테일을 한 경쾌한 메이드. 직설적인 성격으로 손님들을 당황하게 하기도 한다. 특기는 마사지이다.",
        minipack = 0,
    },
    [13400185] = {
        id = 13400185,
        text = "피곤한 얼굴을 한 성숙한 여성. 자주 멍 때리지만, 몸에 예의가 베인 만큼 손님들의 불만이 없다.",
        minipack = 0,
    },
    [13400184] = {
        id = 13400184,
        text = "손님을 대할 때 마치 옆집 오빠를 대하듯이 하는 옆집 아가씨. 서비스가 매우 친절하다.",
        minipack = 0,
    },
    [13400183] = {
        id = 13400183,
        text = "전통적인 외모의 메이드. 성숙하고 멋진 손님에게 약하다. 말 속에는 풍부한 지식이 담겨 있다.",
