    },
    [2101085] = {
        id = 2101085,
        text = "일기장의 구석에는 이렇게 쓰여있다- 연말 행사에서 상으로 스마트폰 하나를 탔다. 와이프한테 선물로 사줬다고 우기면 비상금 겟또다제!",
        minipack = 0,
    },
    [2101087] = {
        id = 2101087,
        text = "빨간색의 붉은 글씨로는 이렇게 쓰여있었다- 기획자가 또 요구하러 오면 꼭 각서를 쓰게 하겠으!!!",
        minipack = 0,
    },
    [2101089] = {
        id = 2101089,
        text = "수납장 정중앙에는 한 입 베어먹은 사과가 놓여있었다. 쓰여있는 것은- [사과 가게에서 보자].",
        minipack = 0,
    },
    [2101091] = {
        id = 2101091,
        text = "프로그래머의 자술: 이번 생에 버그의 수정은 끝나지 않을 것이다.",
        minipack = 0,
    },
    [2101093] = {
        id = 2101093,
        text = "프로그래머의 메모지: 왜 하필 퇴근하기 전에 다음 날에 대한 요구를 하러 오는 건가! 한숨 자고 와서 들어도 되지 않나?",
        minipack = 0,
    },
    [2101095] = {
        id = 2101095,
        text = "안에는 밤샘 작업을 위한 인스턴트 샤브샤브가 들어있다. 맛이 이상할 것 같다. 심지어 옆에는 우렁 칼국수가…",
        minipack = 0,
    },
    [2101097] = {
        id = 2101097,
        text = "휴지로 가득 차 있다. 세일 때 이것만 주구장창 산건가?",
        minipack = 0,
    },
    [2101099] = {
        id = 2101099,
        text = "프로그래머의 심볼인 체크무늬 셔츠가 걸려있다. 빨강 초록 파랑… RGB 다 있네.",
        minipack = 0,
    },
    [2101101] = {
        id = 2101101,
        text = "사업부가 철야할 때 먹는 기능 음료가 들어있다...[핫게임 콜라]",
        minipack = 0,
    },
    [2101103] = {
        id = 2101103,
        text = "업무 비결: 출근하면 기분이 좋아진다. 계속 출근하면 계속 기분이 좋다. 그러니까 출근한다.",
        minipack = 0,
    },
    [2101105] = {
        id = 2101105,
        text = "귀여운 강아지 모양 쿠션. 구석이 젖어있는데 낮잠 때 흘린 침인가…",
        minipack = 0,
    },
    [2101107] = {
        id = 2101107,
        text = "정교하게 만들어진 투구가 들어있다. 위에는 이렇게 쓰여있다- 가장 사랑하는 교관장님에게 바친다.",
        minipack = 0,
    },
    [2101109] = {
        id = 2101109,
        text = "쪽지에는 이렇게 쓰여있다- 내 꿈은 트레버가 되는 거지 마이크가 되는 게 아니다!",
        minipack = 0,
    },
    [2101111] = {
        id = 2101111,
        text = "시들어가는 장미꽃 한 송이가 구석에 누워있다. 기획자가 야근 때문에 사랑하는 이와의 데이트를 잊었던 걸지도 모른다.",
        minipack = 0,
    },
    [2101113] = {
        id = 2101113,
        text = "러브레터랑 장미꽃으로 가득 차있을 줄은 꿈에도 몰랐다. (이렇게 매력적인 기획자가 있다고?)",
        minipack = 0,
    },
    [2101115] = {
        id = 2101115,
        text = "귀여운 당근 모양 쿠션이 들어있다. 펼치면 담요가 된다. (사무실에서 잠을 잔다고?)",
        minipack = 0,
    },
    [2101117] = {
        id = 2101117,
        text = "모 게임의 아이디랑 비번인 것 같다. 하지만 글자가 너무 작아 비번만 보인다- 51851888",
        minipack = 0,
    },
    [2101119] = {
        id = 2101119,
        text = "중앙에 남자의 사진이 놓여있고 주변에는 숫자 [7]로 가득 차다. (뜻을 잘 모르겠다)",
        minipack = 0,
    },
    [2101121] = {
        id = 2101121,
        text = "농구와 관련이 있는 포스터가 잔뜩 붙어 있다. 온통 근육질에 고릴라랑 닮은 캐릭터뿐이다.",
        minipack = 0,
    },
    [2101123] = {
        id = 2101123,
        text = "안에는… XXXL 사이즈의 로리타 드레스가 들어있다!?",
        minipack = 0,
    },
    [2101125] = {
        id = 2101125,
        text = "애니 행사에 대한 계획서가 들어있다. 어렴풋이 '여장 남자 '라는 문구가 눈에 들어왔다.",
        minipack = 0,
    },
    [2101127] = {
        id = 2101127,
        text = "최신형 휴대용 게임기가 들어있고 게임팩도 십여 개 정도 있다. (부르주아네)",
        minipack = 0,
    },
    [2101129] = {
        id = 2101129,
        text = "오피셜 설정집이 한 권 들어있다. 펼쳐보니 츠나코 선생님의 친필싸인이 보인다.",
        minipack = 0,
    },
    [2101131] = {
        id = 2101131,
        text = "게임 누적 충전의 보상과 프로필 테두리에 대한 디자인 시안이 들어 있는 모양이다.",
        minipack = 0,
    },
    [2101133] = {
        id = 2101133,
        text = "종이컵이 한 박스 들어있다. 위에는 귀여운 코토리가 찍혀있다. 아마도 코토리 생일 이벤트 때 나눠줄 덕후들을 위한 콜라컵일지도?",
        minipack = 0,
    },
    [2101135] = {
        id = 2101135,
        text = "신세기 과금 프로젝트 피해자 증명 ' 이라는 이름의 각서 같은 게 있다(뜻을 잘 모르겠다)",
        minipack = 0,
    },
    [2101137] = {
        id = 2101137,
        text = "그림체가 오래된 느낌의 소녀만화가 한 권 들어 있다. 표지에는 피라미드 아래에 서 있는 금발의 소녀가 보인다.",
        minipack = 0,
    },
    [2101139] = {
        id = 2101139,
        text = "메모지가 들어있다- 내일의 패키지 코드는: [탈모가 오기 전에 연애하자].",
        minipack = 0,
    },
    [2101141] = {
        id = 2101141,
        text = "빨간색의 하오리가 들어있다. 뒤에는 총을 든 쿠루미가 찍혀있다.",
        minipack = 0,
    },
    [2101143] = {
        id = 2101143,
        text = "얇은 책이 한 권 들어있다. 그림체를 보아하니 게임 속의 것과는 다르다. 설마 코믹 행사에서 팔 야한 책?",
        minipack = 0,
    },
    [2101145] = {
        id = 2101145,
        text = "데이트 어 라이브 공식 캐릭터 설정집이 들어있다. 꽤 심하게 마모되었다.",
        minipack = 0,
    },
    [2101147] = {
        id = 2101147,
        text = "사물함 안에는 소체 인형이 한 줄로 깔끔하게 정리되어있다. 뭔가 섬뜩하다.",
        minipack = 0,
    },
    [2101149] = {
        id = 2101149,
        text = "아이들이 마시는 음료수가 잔뜩 들어있다. 이걸 좋아하는 사람이 있나?",
        minipack = 0,
    },
    [2101151] = {
        id = 2101151,
        text = "아주 두꺼운 배경 디자인 참고 화집이 들어있다. 상당히 꼼꼼하게 잘 보관되어있다.",
        minipack = 0,
    },
    [2101153] = {
        id = 2101153,
        text = "디자인 담당자가 오랫동안 펼쳐본 226장의 고화질 인체 자세 참고 사진이다. (기묘한 자세는 어떤 애니 작품을 연상시킨다)",
        minipack = 0,
    },
    [2101155] = {
        id = 2101155,
        text = "세심하게 보관된 색지가 들어있다. 머리 모양이 파란 불가사리처럼 보이는… 카드를 든 캐릭터가 그려져 있다. 옆에는 일러스트레이터의 싸인도 있다.",
        minipack = 0,
    },
    [2101157] = {
        id = 2101157,
        text = "일기장이 들어있다- XX 마담이 싸인해 주셨다! 앞으로 이 싸인본은 가보로 전해져 내릴 것이다!",
        minipack = 0,
    },
