    [10991032] = {
        id = 10991032,
        text = "속도 감소",
        minipack = 0,
    },
    [13316288] = {
        id = 13316288,
        text = "「뜻밖의 수확」쿠루미가 갑자기 나타사 탐점 이야기 외에도 재밌는 수집 단서를 알려줬다. 그것은 \"메인 스토리가 일정 단계까지 진행되면 장소에서 퍼즐 조각이 나타난다\"라는 정보였다.",
        minipack = 0,
    },
    [13316287] = {
        id = 13316287,
        text = "「스타 도착」오랜만의 휴가에, 나는 조수로써 슈퍼스타 미쿠와 함께 단풍잎 경치로 유명한 산장에 왔지만, 운이 없게 소나기가 내려 우리의 물장난 흥을 깨버렸다.",
        minipack = 0,
    },
