        minipack = 0,
    },
    [13313513] = {
        id = 13313513,
        text = "이세계 사악 세력의 사락한 제사 의식을 발견했습니다. 코토리는 의식을 파괴할 인원이 필요하다고 합니다.",
        minipack = 0,
    },
    [27182] = {
        id = 27182,
        text = "2021 설날 축원 신물. 정교한 잉어 벽지가 축복을 담고 있다. 모든 일이 이루어지는 행복한 2021년이 되길 바랍니다!",
        minipack = 0,
    },
    [13313511] = {
        id = 13313511,
        text = "하늘 해적의 본거지에서 대량의 물자를 획득했습니다. 운반할 인력이 필요합니다.",
        minipack = 0,
    },
    [13313509] = {
        id = 13313509,
        text = "문명의 하늘 해적은 매우 날뛰고 있습니다. 코토리는 높은 전투력의 정령을 보내 섬멸해야 한다고 합니다.",
        minipack = 0,
    },
    [13313507] = {
        id = 13313507,
        text = "적 전함에 탑재된 일부 무기로 「공중함」을 무장할 수 있습니다. 코토리는 완료할 인원이 필요하다고 합니다.",
        minipack = 0,
    },
    [63578] = {
        id = 63578,
        text = "시공을 뛰어넘어 너와 다시 만날 거야——\n이곳은 오리가미의 기억 속 세계가 구현된 「기억 공간」으로, 이 공간의 시간은 몹시 불안정합니다. 이 공간을 탐색하며 다양한 퀘스트를 완료하고 「기억 데이트」를 개방해 데이트에서 오리가미를 찾아야 합니다.\n기억 데이트에 입장하면 도중에 퇴장할 수 없으며, 데이트를 완료하거나 퇴장 시 기억이 끊겨 더는 데이트에 입장할 수 없습니다. 데이트 중의 선택지를 신중하게 선택하세요.\n각 「기억 데이트」마다 1개의 기억 파편이 숨겨져 있습니다. 모든 기억 파편을 수집하면 최종 데이트를 개방할 수 있습니다.\n\n시간선 도약:\n라타토스크가 개발한 특수 장치는 기억 공간의 에너지를 수집할 수 있습니다.\n일정량의 에너지를 소모하면 시간선을 도약할 수 있고, 현재 기억에서 이탈해 새로운 기억으로 진입할 수 있습니다.\n시간선 도약 시 새로운 「기억 데이트」가 등장하며, 이전의 기억 데이트는 다시 진입할 수 없으므로, 데이트를 완료한 후 시간 도약을 진행하는 것이 좋습니다.",
        minipack = 0,
    },
    [32302] = {
        id = 32302,
        text = "",
        minipack = 0,
    },
    [13313503] = {
        id = 13313503,
        text = "「공중함」안개 구역에 머물고 있습니다. 선원 몇 명을 밖으로 보내 정찰해야 합니다.",
        minipack = 0,
    },
    [13313501] = {
        id = 13313501,
        text = "「공중함」항해와 전투 중에 파손된 곳이 있습니다. 전문 지식을 지닌 선원을 보내 수리해야 합니다.",
        minipack = 0,
    },
    [13313499] = {
        id = 13313499,
        text = "당신의 도움 덕분에, 이 구역의 사람들은 평화를 얻었습니다. 그들은 진심을 담은 선물로 보답합니다.",
        minipack = 0,
    },
    [13313498] = {
        id = 13313498,
        text = "고대의 유적에는 신비한 보물이 남아있습니다. 인연이 닿는 자만이 얻을 수 있습니다.",
        minipack = 0,
    },
    [42076] = {
        id = 42076,
        text = "SS급 에너지 보석, 랜덤으로 [야마이 카구야]의 임의 스킬 SS급 보석 획득.（획득 후 자동 사용）",
        minipack = 0,
    },
    [13313497] = {
        id = 13313497,
        text = "사악한 세력을 처치한 후 신명의 보상을 얻었습니다. 반짝 빛나는 보물 상자가 함선 안에 나타났습니다.",
        minipack = 0,
    },
    [13313495] = {
        id = 13313495,
        text = "전장을 정리하던 도중 전함 잔해에서 뜻밖의 보물 상자를 획득했습니다.",
        minipack = 0,
    },
    [13313493] = {
        id = 13313493,
        text = "어인족 군단이 많은 포로를 포획했습니다. 그들을 구출하세요.",
        minipack = 0,
    },
    [13313491] = {
        id = 13313491,
        text = "어인족이 물러납니다. 놈들을 추격해 더 큰 승리를 성취하세요.",
        minipack = 0,
    },
    [13313490] = {
        id = 13313490,
        text = "어인족 군단의 보급 함대를 공격해 적의 보급을 차단하세요.",
        minipack = 0,
    },
    [13313487] = {
        id = 13313487,
        text = "척후함을 처치하고, 어인족 군단을 매복 지점으로 끌어오세요.",
        minipack = 0,
    },
    [13313485] = {
        id = 13313485,
        text = "아틀란티스에서 악명 높은 하늘 해적을 처리하고 사람들을 해방시키세요.",
        minipack = 0,
    },
    [13313483] = {
        id = 13313483,
        text = "심해에서 무작위로 나타나는 신비의 집, 아틀란티스에서 한때 유행했던 아름다운 비보 「바다의 고향」을 판다고 한다.",
        minipack = 0,
    },
    [13313482] = {
        id = 13313482,
        text = "천살 먹은 조개에서 신의 빛이 은은하게 나고 있다. 비보 「태양의 빛」은 어느 조개가 훔쳐 간 것이라고 한다.",
        minipack = 0,
    },
    [13313481] = {
        id = 13313481,
        text = "심해에서 해초로 뒤덮인 신비한 조각상들, 권력의 상징인 비보 「포세이돈의 힘」이 바로 이 조각상들 중의 손에 있다고 한다.",
        minipack = 0,
    },
    [13313479] = {
        id = 13313479,
        text = "버려진 제사장, 갑작스러운 전쟁으로 인해, 보물 「태양 주술 가면」도 가져갈 시간이 없었다.",
        minipack = 0,
    },
    [13313477] = {
        id = 13313477,
        text = "어둠의 어인족의 모함 「고래」를 처치하고, 저주에 의해 타락한 암흑의 아틀란티스를 구하세요!",
        minipack = 0,
    },
    [13313475] = {
        id = 13313475,
        text = "어인족의 함대 규모는 무서울 정도로 거대합니다. 도망치던 중 신비한 수중 궁전을 발견했습니다. 궁전 수비병을 처치하세요.",
        minipack = 0,
    },
    [13313474] = {
        id = 13313474,
        text = "적은 심해에서 거주하고 있는 사악한 어인족인 것을 확인했습니다. 어인족은 어떠한 힘에 의해 조종당해 총 공격을 하는 것 같습니다.",
        minipack = 0,
    },
    [13313471] = {
        id = 13313471,
        text = "아무런 원한도 없는 아틀란티스 함대가 「공중함」을 철저하게 파괴하려고 합니다. 코토리가 포위망을 뚫고 심해로 가는 것을 제안합니다.",
        minipack = 0,
    },
    [13313469] = {
        id = 13313469,
        text = "아틀란티스 황실 함대가 공격을 퍼붓습니다. 반드시 포위망을 뚫어내야 합니다.",
        minipack = 0,
    },
    [13313467] = {
        id = 13313467,
        text = "메소포타아 하늘 해적의 본거지를 찾아내고, 섬멸 작전에 참여하세요!",
        minipack = 0,
