    [13313455] = {
        id = 13313455,
        text = "문명의 통치자는 항상 자신의 운명을 지배해야하지만, 비보 「고양이의 예언」은 자신의 유실을 예견하지 못했다.",
        minipack = 0,
    },
    [13313453] = {
        id = 13313453,
        text = "고대 대식묘족이 비보 「황금 어포」를 만들었다. 진실된 신앙을 가진 소금파 인원만이 얻을 수 있다고 한다.",
        minipack = 0,
    },
    [13313451] = {
        id = 13313451,
        text = "황야에 얼려져 있는 제단, 메소포타아의 비보 「얼음 주술 가면」이 묻혀 있다고 한다.",
        minipack = 0,
    },
    [11221182] = {
