    [13311423] = {
        id = 13311423,
        text = "[보물 파편]\n평화를 사랑하는 인어일지라도, 삼지창을 적을 향해 세우는 날이 온다. \n(전투 중, 일정 시간마다 직접 피해가 1회 증가한다)",
        minipack = 0,
    },
    [13311420] = {
        id = 13311420,
        text = "[보물 파편]\n쿤타아 주술사가 사용하는 점술 수정 해골, 제3의 눈에는 비범한 마력이 담겨 있다. \n(전투 중, 모든 아군 정령의 공격력이 증가한다)",
