    },
    [13311417] = {
        id = 13311417,
        text = "[보물 파편]\n오리칼쿰은 아틀란티스 문명의 핵심 에너지석이며, 태양 빛을 에너지로 전환한다. \n(전투 중, 신성속성, 암흑 피해가 증가한다)",
        minipack = 0,
    },
    [1706135] = {
