    [10981197] = {
        id = 10981197,
        text = "[현실 침입] 관통률 9% 증가",
        minipack = 0,
    },
    [10981205] = {
        id = 10981205,
        text = "[현실 침입] 본체가 적을 향해 돌진할 시, 제자리로 돌아와 다수의 공을 캐릭터 뒤에 소환한 후, 가시 모양으로 변형 시켜 적을 향해 발사한다. 총 1300%의 암흑 속성 피해를 입힌다",
        minipack = 0,
    },
    [10981213] = {
        id = 10981213,
        text = "[현실 침입] 에너지 소모 4포인트 감소",
        minipack = 0,
    },
    [10981221] = {
        id = 10981221,
        text = "[데이터 손상]에 표기가 된 적은 출혈 효과가 적용되며, 매 초 마리나 공격력 80%의 피해를 입고, 입는 피해가 6초간 15% 증가한다(데이터 손상: 10초마다 랜덤으로 적 3명에게 표식을 남겨, 표식이 있는 목표는 3초 동안 기절한다. 마리나가 표식이 있는 목표를 공격 시 공격력이 30% 증가한다)",
        minipack = 0,
    },
    [10981229] = {
        id = 10981229,
        text = "HP가 50% 미만일 경우 지속 회복 효과를 획득하며, 초당 5% 회복, 6초간 지속. 회복 시간 동안 스턴, 빙결, 속도 감소 유형의 제어 효과 면역. 해당 효과는 60초의 쿨타임이 적용된다.",
        minipack = 0,
    },
    [20042] = {
        id = 20042,
        text = "캐릭터: 토키사키 쿠루미\n\n크리스마스? 나한테 부탁한다면 영원히 크리스마스를 보내는 것도 가능할지도 몰라.",
        minipack = 0,
    },
    [21066] = {
        id = 21066,
        text = "캐릭터: 토키사키 쿠루미\n\n신위영장-3번 <Elohim>. 흑적색의 고딕 스타일 영장, 쿠루미의 고귀하면서도 우아한 여왕님 성향과 잘 맞는다.",
        minipack = 0,
