    [2108001] = {
        id = 2108001,
        text = "시련: 뫼비우스",
        minipack = 0,
    },
    [2108003] = {
        id = 2108003,
        text = "시련: 허상",
        minipack = 0,
    },
    [2108005] = {
        id = 2108005,
        text = "모든 사건은 끊임없이 변화하며, 모든 준칙은 왜곡된다. 변이의 격랑은 끝없이 몰려오며, 왕좌는 한없이 떨리고 있다. 그러나 국왕의 손에 쥔 검은 조금의 동요조차 보이지 않는다.",
        minipack = 0,
    },
    [2108007] = {
        id = 2108007,
        text = "1. 모의 시련은 기간 한정 체험 이벤트이므로, 참여 시간에 주의하세요.",
        minipack = 0,
    },
    [2108009] = {
        id = 2108009,
        text = "3. 모의 시련의 주인공은 시라이 쿠로코입니다. 많은 참여 바랍니다.",
        minipack = 0,
    },
    [2108011] = {
        id = 2108011,
        text = "정말 해당 정령의 체험 모드에 입장하겠습니까?",
        minipack = 0,
    },
    [2108013] = {
        id = 2108013,
        text = "모의 시련: 진지",
        minipack = 0,
    },
    [2108015] = {
        id = 2108015,
        text = "유격전의 특징은 적진에 돌입해 소규모의 전투로 적의 전선을 교란하는 것입니다. 각개 작전의 우세를 최대한 활용하세요.",
        minipack = 0,
    },
    [2108017] = {
        id = 2108017,
        text = "특공 작전은 특정 목표를 대상으로 지정 타격을 진행하는 작전이며, 고효율과 정밀성이 그 특징입니다. 속전속결로 작전을 수행하세요.",
        minipack = 0,
    },
    [2108019] = {
        id = 2108019,
        text = "번외: 미혹",
        minipack = 0,
    },
    [2108021] = {
        id = 2108021,
        text = "우연이라 해도, 그 역시 필연이다. 토카의 영장이 갑자기 이상한 형태를 보이기 시작했다. 과연 무엇이 눈 앞에 펼쳐지게 될까.",
        minipack = 0,
    },
    [2108023] = {
        id = 2108023,
        text = "마음을 직시하고 칼끝을 맞댄다. 과거의 자신을 맞설 때는 두려움이 들기 마련이다. 하지만 그렇기 때문에 길을 찾는 이는 성장하게 된다.",
        minipack = 0,
    },
    [2108025] = {
        id = 2108025,
        text = "음모",
        minipack = 0,
    },
    [2108027] = {
        id = 2108027,
        text = "알 수 없는 적의 습격이 점차 다가오고, 마유리도 전투에 투입된다. 이 세계를 처음 마주하는 마유리, 과연 인간의 다른 면을 어떻게 받아들일 것인가.",
        minipack = 0,
    },
    [2108029] = {
        id = 2108029,
        text = "어둠속에 숨은 적이 모습을 드러내자, 금빛 날개가 펼쳐진다. 함정 vs 용기, 승리를 거두는 것은 과연 누가 될까.",
        minipack = 0,
    },
    [2108031] = {
        id = 2108031,
        text = "「해후」",
        minipack = 0,
    },
    [2108033] = {
        id = 2108033,
        text = "다시 현계한 정령은 마치 이 세계에 관심이 많은 듯하다. 하지만 그녀의 등장 방식을 좋아하지 않는 사람도 있다.",
        minipack = 0,
