    },
    [950076] = {
        id = 950076,
        text = "쿠루미는 어쩌면 자신이 원해서 사악한 정령이 된 게 아닐지도 몰라... 난... 난 반드시 쿠루미를 구하겠어!",
        minipack = 0,
    },
    [11203049] = {
        id = 11203049,
        text = "[원무검참] 3번 째 돌격 후 캐릭터의 뒤에서 작은 범위의 검기 공격을 가한다. 스킬이 자신의 공격력의 980%에 해당하는 신성 피해를 입힌다. \n[빛나는 칼날] 1회의 중격 마무리를 추가한다. 스킬이 자신의 공격력의 820%에 해당하는 신성 피해를 입힌다.",
        minipack = 0,
    },
    [11203048] = {
