        minipack = 0,
    },
    [13310610] = {
        id = 13310610,
        text = "은은한 꽃향기가 마치 꽃이 가득한 정원에 있는 듯한 느낌을 준다. 2021년 02월 05일 이후 봄의 시작에서 계화꽃 탕원을 만드는 데 사용할 수 있다.",
        minipack = 0,
    },
    [13310618] = {
