    [13313074] = {
        id = 13313074,
        text = "큰 뼈다귀는 견신족이 좋아하는 음식이며, 영원히 썩지 않는 황금 뼈다귀는 견신족의 풍년을 예시한다.",
        minipack = 0,
    },
    [13313082] = {
        id = 13313082,
        text = "비린내가 나지 않아도, 황금 어포가 매소포타아의 가장 인기 있는 액세서리가 되는 것에 변함이 없다.",
        minipack = 0,
    },
    [13313090] = {
        id = 13313090,
        text = "평화를 사랑하는 인어일지라도, 삼지창을 적을 향해 세우는 날이 온다. 그것은 건들 수 없는 바다의 제왕의 권력이다.",
        minipack = 0,
    },
    [13313098] = {
        id = 13313098,
        text = "[공중함 부품]\n함선 메인 동력, 함선의 가속에 순간적인 파워를 제공한다. \n전투 중, 아군의 공격(보호막 흡수 포함)은 적의 방어력을 3턴 동안 20% 감소시키며, 중첩할 수 없다.",
        minipack = 0,
    },
    [13313106] = {
        id = 13313106,
        text = "[공중함 부품]\n영상 분석 장치, 결정에 대한 정확성에 영향을 준다. \n전투 시작 시, 적의 전투 속도를 3턴 동안 30% 감소시킨다.",
        minipack = 0,
    },
    [13313114] = {
        id = 13313114,
        text = "[공중함 부품]\n다재다능한 부품, 공중함의 운행력을 늘려준다. \n탐색 중, 추가로 5%의 확률로 보호막 업그레이드 재료가 드랍된다[질드 배터리]",
        minipack = 0,
    },
    [13313122] = {
        id = 13313122,
        text = "[공중함 부품]\n공중함을 떠나 탐색이 가능한 무신 조종 장치이다. \n탐색 중, 2급 보상 드랍 확률이 15% 증가한다!",
        minipack = 0,
    },
    [13313130] = {
        id = 13313130,
        text = "[방어실 업그레이드 재료]\n방어 시스템에 더 많은 에너지를 제공하는 초문명 원석.",
        minipack = 0,
