    },
    [13313394] = {
        id = 13313394,
        text = "바다는 인어족에게 생존할 음식을 제공했고, 아틀란티스인은 흡수과 감사를 배웠다.",
        minipack = 0,
    },
    [13313402] = {
        id = 13313402,
        text = "바람과 파도를 극복하지 못하는 선장은 난관을 뚫고 신대륙을 발견하지 못한다.",
        minipack = 0,
    },
    [13313410] = {
        id = 13313410,
        text = "오리칼쿰의 에너지는 매우 불안정하여, 에너지 광폭화를 막기 위해, 아틀란티스인은 특유의 기술을 보유하고 있다.",
        minipack = 0,
    },
    [13313418] = {
        id = 13313418,
        text = "타락은 검은색 개 부족은 왕실과 손을 잡고 다른 부족을 끊임없이 침략하고 있습니다. 놈들에게 제대로 된 교육을 해줄 때가 됐습니다!",
        minipack = 0,
    },
    [13313426] = {
        id = 13313426,
        text = "대천견이 전능한 제3의 눈으로 중생을 바라보며, 비보 「통치의 눈」에는 엄청난 양의 힘이 담겨져 있습니다.",
        minipack = 0,
    },
    [13313434] = {
        id = 13313434,
        text = "쿤타아 혁명군의 반격 작전을 따라, 왕실군 날개 측 함대를 섬멸하세요.",
        minipack = 0,
    },
    [13313442] = {
        id = 13313442,
        text = "메소포타아 주황색 함대의 추격을 받고 있습니다. 이제 전투에 응할 때입니다.",
        minipack = 0,
    },
    [13313450] = {
        id = 13313450,
        text = "설팡파와 소금파의 모든 힘을 모아, 흑사자 군단의 모함 「사자」와 결전을 치르고, 백 년 동안 지속 된 전쟁을 종결지으세요!",
        minipack = 0,
    },
    [13313458] = {
        id = 13313458,
        text = "메소포타아에서 악명 높은 하늘 해적을 처리하고 사람들을 해방시키세요.",
        minipack = 0,
