    [63586] = {
        id = 63586,
        text = "서약자는 보석 주조 중 재료를 사용해 A~SS급 보석 또는 S~SS급 도면을 합성할 수 있습니다.\n\n먼저 주조할 보석의 등급을 선택한 후 정령을 선택하고, 마지막으로 스킬을 선택하면 주조를 진행할 수 있습니다.\n\n보석의 등급마다 주조에 필요한 재료가 다르며, 정령 또는 스킬의 랜덤 설정 여부에 따라 재료 소모량이 변화합니다.",
        minipack = 0,
    },
    [11211227] = {
        id = 11211227,
        text = "[진격모드]에서 아이즈·발렌슈타인 방어 10% 감소, 입히는 크리티컬 피해와 관통 피해가 35%만큼 대폭 증가.",
        minipack = 0,
    },
    [11211225] = {
        id = 11211225,
        text = "아이즈.발렌슈타인 효과: [질주모드]에서 관통율 15% 증가, 관통 피해 10% 증가. [진격모드]에서 크리티컬 확률 15% 증가, 크리티컬 피해10% 증가.",
