    [3310012] = {
        id = 3310012,
        text = "12. 피해 점유율은 동아리 멤버의 개인 보상이므로, 개인이 기간 동안 모든 보스에게 입힌 피해를 계산해, 결산 후 그에 상응하는 단계의 전리품을 얻습니다.",
        minipack = 0,
    },
    [3310010] = {
        id = 3310010,
        text = "10. 작전 순위는 동아리 내 개인 레이드 순위와 동아리 간의 경쟁 순위로 구성되어 있습니다. 개인 사냥몰이 포인트는 동아리 구성원이 현재 주기에서 보스에게 입힌 피해를 환산해 결정됩니다. 동아리 순위는 현재 주기 내 동아리 보스 도전 진행도(최고 보스 레벨, 입힌 피해)에 따라 결정되며, 다음 주기에 지난 주기의 동아리 경쟁 순위가 공개됩니다.",
        minipack = 0,
    },
    [290022] = {
        id = 290022,
        text = "Enhance Sephira 1 time",
        minipack = 0,
    },
    [3310007] = {
        id = 3310007,
        text = "7. 각 주기마다 동아리 구성원은 보스 도전 횟수가 3회 주어집니다. 한 레벨의 보스의 처치에 성공할 때마다 도전 횟수가 1 증가하지만, 최대 횟수를 초과할 수는 없습니다.",
        minipack = 0,
    },
    [3310006] = {
        id = 3310006,
        text = "6. 동아리 보스의 전투 속성과 총 HP는 레벨에 따라 증가합니다. 여러 파티가 동시에 보스에게 도전할 경우, 각 파티의 전투가 완료된 후 보여지는 총 HP 결산 정보가 다를 수 있습니다.",
        minipack = 0,
    },
    [3310004] = {
        id = 3310004,
        text = "4. 각 약점 던전은 동아리 보스의 전투 속성(최대 HP, 공격력, 방어력)과 대응하며, 도전 성공 횟수가 많을수록 도전 단계에서 보스의 전투 속성이 더 많이 약화(최대 HP약화는 동아리 보스의 총 HP와 동일하게 적용)됩니다. 약점 던전에서 작전에 실패할 경우에도 보상을 획득할 수 있지만, 도전 성공 횟수에는 반영되지 않습니다.",
