    [20176] = {
        id = 20176,
        text = "유형: 코스튬\n캐릭터: 야토가미 토카\n2021년 4월 10일, 생일 파티의 주인공, 앞으로도 이 세계를 계속 사랑해주길 바래, 나의 사랑스러운 공주님!",
