    [3210585] = {
        id = 3210585,
        text = "모든 출전 캐릭터 마력 피해+10%",
        minipack = 0,
    },
    [11312001] = {
        id = 11312001,
        text = "[산달폰(가짜)] 스킬로 인한 물리 피해 1000%까지 증가 가능. \n[하니엘] 스킬로 인한 마력 피해 1800%까지 증가 가능.",
        minipack = 0,
    },
    [11312009] = {
        id = 11312009,
        text = "[쇄성발산/마법구] 크리티컬 확률 8% 증가",
        minipack = 0,
    },
    [11312017] = {
        id = 11312017,
        text = "[쇄성발산/마법구] 4단계 공격 시 2개의 별을 생성한다. 스킬이 공격력의 400%에 해당하는 마력 피해를 입힌다. \n[마법구] 날라가는 속도는 감소하지만, 접촉한 적에게 지속적으로 피해를 입힌다. 초당 최대로 2회의 피해를 입힌다. 매번 공격력의 50%만큼 마력 피해를 입힌다.",
        minipack = 0,
    },
    [11312025] = {
        id = 11312025,
        text = "[쇄성발산/마법구] 공격 효과 범위 20% 증가",
        minipack = 0,
    },
    [11312033] = {
        id = 11312033,
        text = "[변신] 스킬 사용 후 7초 동안 공격속도 2% 증가",
        minipack = 0,
    },
    [11312041] = {
        id = 11312041,
        text = "[변신] 스킬 사용 후 6초 동안 이동속도 10% 증가",
        minipack = 0,
    },
    [11312049] = {
        id = 11312049,
        text = "[변신] 스킬 쿨타임 1.5초 감소",
        minipack = 0,
    },
    [11312057] = {
        id = 11312057,
        text = "[마법성옥/성계여행] 목표 명중 후 3초 동안 목표의 크리티컬 저항률 6% 감소",
