    [30416] = {
        id = 30416,
        text = "30316",
        minipack = 0,
    },
    [11312073] = {
        id = 11312073,
        text = "[마법성옥/성계여행] 스킬 사용 후 30%의 확률로 1개의 보석 에너지를 회복한다",
        minipack = 0,
