    [11312081] = {
        id = 11312081,
        text = "[모에 천지/악운 권속] 크리티컬 확률 2% 증가",
        minipack = 0,
    },
    [11312089] = {
        id = 11312089,
        text = "[모에 천지/악운 권속] 적이 사용한 탄환류의 스킬을 홍당무로 만들 수 있다. 스킬이 공격력의 400%에 해당하는 피해를 입힌다. [설명: 탄환류의 스킬은 미사일, 직선으로 날라오는 탄환 등이다. 예를 들면 AST 오리가미의 '극한 사격 ' 이다, 단 AST 오리가미의 '핵평사자 ' 제외]\n[악운 권속] 권속 수량이 12마리로 증가한다.",
        minipack = 0,
    },
    [11312097] = {
        id = 11312097,
        text = "[모에 천지/악운 권속] 스킬 피해 15% 증가",
        minipack = 0,
    },
    [11312105] = {
        id = 11312105,
        text = "나츠미가 피해를 입힐 때 5%의 확률로 목표에게 지속적으로 마녀 저주를 적용한다. \n[설명: 마녀 저주 디버프 효과: 마녀 저주가 적용 된 적은 3초 동안 초당 나츠미 공격력의 30%만큼 피해를 받으며 5단계까지 중첩할 수 있다. 목표의 방어력은 해당 피해에 적용이 된다.]",
        minipack = 0,
    },
