    [405022] = {
        id = 405022,
        text = "지혜와 용맹을 겸비한 무희, 한때 부상을 당한 오빠를 대신하여 군대를 지휘해 적의 침입을 격퇴했다. 세피라는 지혜이며, 2개의 랜덤 속성을 지니고 있다.",
        minipack = 0,
    },
    [17114] = {
        id = 17114,
        text = "[최상의 특미] 달달하고 부드러운 찹쌀에 시원한 과일을 올려 한 입에 먹으면 상당한 만족감을 느낄 수 있다.",
        minipack = 0,
    },
    [18138] = {
        id = 18138,
        text = "[완벽한 수공예품] 하늘의 별처럼 화사하게 핀 꽃, 생명력이 강하다.",
        minipack = 0,
    },
    [10203002] = {
        id = 10203002,
        text = "전방으로 돌진한 후 빠르게 3차례 참격을 가하고 레이저포를 발사하여 전방의 적을 지속적으로 폭격한다. \n참격： 적에게 공격력 120%만큼 물리 피해를 3회 입힌다. \n폭격： 적에게 공격력 100%만큼 뇌전 피해를 6회 입힌다.",
        minipack = 0,
    },
    [20186] = {
        id = 20186,
        text = "유형: 영장\n캐릭터:이츠카 시오리\n그냥 메이드복으로는 좀 부족한 것 같아요. 움직이는 꼬리와 영민한 귀까지 더해져 귀여운 메이드로 변신하세요!",
        minipack = 0,
    },
    [10203018] = {
        id = 10203018,
        text = "[AST 제식 광검] 크리티컬 확률 +4%.",
        minipack = 0,
    },
    [10203026] = {
