        minipack = 0,
    },
    [405121] = {
        id = 405121,
        text = "검술 실력이 유명한 나무의 요정, 대지와 숲의 힘을 이용하는 데 능숙하다. 세피라는 기초이며, 4개의 랜덤 속성을 지니고 있다.",
        minipack = 0,
    },
    [2100144] = {
        id = 2100144,
        text = "2. 매주 월~토요일에 각 챕터가 번갈아 개방됩니다. 매주 일요일에는 두 챕터가 모두 개방됩니다.",
        minipack = 0,
    },
    [2100145] = {
