        minipack = 0,
    },
    [14210205] = {
        id = 14210205,
        text = "휴식의 시간이 다가왔다. 하지만 꿈은 결코 쉬는 법이 없다. 다음 집결에는 또 다른 정상에 도전할 것이다.",
        minipack = 0,
    },
    [14210213] = {
        id = 14210213,
        text = "새로운 정령 발견! 식별명 '허밋'의 정령 요시노. 유인 계획 개시!",
        minipack = 0,
    },
    [14210221] = {
        id = 14210221,
        text = "콘서트를 중단시킨 전투, 결코 용서할 수 없다! —— '당신들은 팬의 자격이 없어요!'",
        minipack = 0,
    },
    [14210229] = {
        id = 14210229,
        text = "절망. 폭동. 포악. 나의 소환에 응하라, 나헤마! 강대한 칠흑의 반전체, 첫 등장!",
        minipack = 0,
    },
    [14210237] = {
        id = 14210237,
        text = "마유리 극장 정식 개방. 만남, 그것이야말로 우리가 존재하는 의미!",
        minipack = 0,
    },
    [14210245] = {
        id = 14210245,
        text = "겨울 대작전 정식 개방. 귀여운 외투를 입고 있어도, 봐주는 일은 없다.",
        minipack = 0,
    },
    [14210253] = {
        id = 14210253,
        text = "설날 이벤트 핫게임의 비밀 정식 개방. 무고한 연구진을 구출하고 미쳐버린 개발자 보스를 처치하라!",
        minipack = 0,
    },
    [14210261] = {
        id = 14210261,
        text = "개학 시즌 시작! 봄 특훈 주간이 정식으로 막을 올립니다. 힘과 지혜를 함께 단련하세요!",
        minipack = 0,
    },
    [14210269] = {
        id = 14210269,
        text = "클리포트의 나무 개방, 작전 목표 확인, 마왕 - 아스타로트 처치. 세피라 세계를 정화하라!",
        minipack = 0,
    },
    [14210277] = {
        id = 14210277,
        text = "DEM의 힘을 얻은 오리가미는 복수의 전의를 다시금 불태운다! —— '이번에는 반드시 정령에게 복수하겠어!'",
        minipack = 0,
    },
    [14210285] = {
        id = 14210285,
        text = "관통 속성이 다시 돌아오고, 셰키나·토카의 봄이 다가왔습니다. 검을 손에 쥐고 작전을 시작하세요!",
        minipack = 0,
